For `format_netstring`, we validate input types, encode strings to UTF-8, compute the payload length, and construct the netstring with proper ASCII-encoded length, colon, payload, and comma. For `parse_netstring`, we validate input types, locate the colon, verify the length portion (digits, no leading zeros), extract the length, ensure sufficient bytes for the payload and trailing comma, and return the parsed payload and remainder.

```python
def format_netstring(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    elif not isinstance(data, bytes):
        raise ValueError("data must be bytes or str")
    length = len(data)
    length_str = str(length).encode('ascii')
    return length_str + b":" + data + b","


def parse_netstring(blob):
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError("blob must be bytes or bytearray")
    colon_pos = blob.find(b":")
    if colon_pos == -1:
        raise ValueError("missing colon")
    length_bytes = blob[:colon_pos]
    if not length_bytes:
        raise ValueError("empty length")
    for b in length_bytes:
        if not 48 <= b <= 57:
            raise ValueError("invalid length character")
    if len(length_bytes) > 1 and length_bytes[0] == 48:
        raise ValueError("leading zero in length")
    try:
        length = int(length_bytes.decode('ascii'))
    except ValueError:
        raise ValueError("invalid length")
    payload_start = colon_pos + 1
    payload_end = payload_start + length
    if payload_end + 1 > len(blob):
        raise ValueError("incomplete payload or missing comma")
    if blob[payload_end] != 44:
        raise ValueError("missing trailing comma")
    payload = blob[payload_start:payload_end]
    remainder = blob[payload_end + 1:]
    return (payload, remainder)
