import re
import string

def slugify(text, max_len=None, separator='-'):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not isinstance(separator, str) or len(separator) != 1 or separator not in ('-', '_', '.'):
        raise ValueError("separator must be one of '-', '_', '.'")
    if max_len is not None:
        if not isinstance(max_len, int) or max_len <= 0:
            raise ValueError("max_len must be a positive integer or None")

    text_lower = text.lower()
    slug = []
    for c in text_lower:
        if c in string.ascii_lowercase or c in string.digits:
            slug.append(c)
        else:
            slug.append(separator)
    slug = ''.join(slug)

    slug = re.sub(rf"{re.escape(separator)}+", separator, slug)
    slug = slug.strip(separator)

    if max_len is not None:
        slug = slug[:max_len]
        slug = slug.rstrip(separator)

    return slug
