To implement the required functions, we first validate the input string in `parse_card` by checking its length and structure. The suit is always the last character, and the rank is the preceding part. We handle "10" as a special case for three-character strings. For two-character strings, we check valid rank letters (J, Q, K, A) or digits (2-9). In `format_card`, we validate the rank and suit inputs, converting the rank to the appropriate string representation (e.g., "10" for 10, "J" for 11) and ensuring the suit is lowercase.

```python
def parse_card(card_str):
    card_str = card_str.strip().lower()
    if len(card_str) == 2:
        rank_part, suit_char = card_str[0], card_str[1]
    elif len(card_str) == 3:
        if card_str[:2] != '10':
            raise ValueError
        rank_part, suit_char = '10', card_str[2]
    else:
        raise ValueError
    if suit_char not in 'cdhs':
        raise ValueError
    if rank_part == '10':
        return (10, suit_char)
    if rank_part in '23456789':
        return (int(rank_part), suit_char)
    if rank_part in 'jqk':
        rank_map = {'j': 11, 'q': 12, 'k': 13}
        return (rank_map[rank_part], suit_char)
    if rank_part.lower() == 'a':
        return (14, suit_char)
    raise ValueError

def format_card(rank, suit):
    if not isinstance(rank, int) or isinstance(rank, bool):
        raise ValueError
    if not (2 <= rank <= 14):
        raise ValueError
    if len(suit) != 1 or suit.lower() not in 'cdhs':
        raise ValueError
    suit = suit.lower()
    if rank == 10:
        rank_str = '10'
    elif 2 <= rank <= 9:
        rank_str = str(rank)
    elif rank == 11:
        rank_str = 'J'
    elif rank == 12:
        rank_str = 'Q'
    elif rank == 13:
        rank_str = 'K'
    elif rank == 14:
        rank_str = 'A'
    else:
        raise ValueError
    return f"{rank_str}{suit}"
