For the Möbius function, we factorize `n` using trial division, checking for squared prime factors. If any exist, return 0. Otherwise, count distinct primes and return `(-1)^k`. For the Mertens function, we precompute a list of Möbius values up to `n` and sum them cumulatively.

```python
def mobius_mu(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError
    if n == 1:
        return 1
    current = n
    k = 0
    d = 2
    while d * d <= current:
        if current % d == 0:
            count = 0
            while current % d == 0:
                current //= d
                count += 1
            if count > 1:
                return 0
            k += 1
        else:
            d += 1
    if current > 1:
        k += 1
    return (-1) ** k

def mertens_m(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError
    total = 0
    for i in range(1, n + 1):
        total += mobius_mu(i)
    return total
