```python
def legendre_symbol(a, p):
    if p < 3 or p % 2 != 1:
        raise ValueError("p must be an odd prime >= 3")
    if not (isinstance(p, int) and isinstance(a, int)):
        raise ValueError("Inputs must be integers")
    if not is_prime(p):
        raise ValueError("p must be prime")
    a_mod = a % p
    if a_mod == 0:
        return 0
    exponent = (p - 1) // 2
    result = pow(a_mod, exponent, p)
    return 1 if result == 1 else -1

def jacobi_symbol(a, n):
    if n < 1 or n % 2 == 0:
        raise ValueError("n must be a positive odd integer")
    if not (isinstance(n, int) and isinstance(a, int)):
        raise ValueError("Inputs must be integers")
    a = a % n
    if a == 0:
        return 0
    if a == 1:
        return 1
    if n == 1:
        return 1
    # Remove factors of 2
    k = 0
    while a % 2 == 0:
        a //= 2
        k += 1
    # Apply sign for 2^k
    if k % 2 == 1:
        n_mod_8 = n % 8
        if n_mod_8 in (3, 5):
            result = -1
        else:
            result = 1
    else:
        result = 1
    # Reciprocal case
    if a % 4 == 3 and n % 4 == 3:
        result *= -1
    a, n = n, a
    n = a
    return result * jacobi_symbol(a, n)

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(n**0.5) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True
