To compute the Carmichael function $\lambda(n)$, we first validate the input to ensure it is a positive integer. For $n = 1$, we return 1 directly. For $n > 1$, we factor $n$ into its prime powers and compute $\lambda(p^k)$ for each prime $p$ and exponent $k$, applying the special rules for $p = 2$ and general odd primes. Finally, we compute the least common multiple (LCM) of all $\lambda(p^k)$ values to obtain $\lambda(n)$.

```python
import math

def carmichael_lambda(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError
    if n == 1:
        return 1

    def prime_factors(n):
        factors = {}
        while n % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            n = n // 2
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n = n // i
            i += 2
        if n > 1:
            factors[n] = 1
        return factors

    factors = prime_factors(n)
    lambdas = []

    for p, exp in factors.items():
        if p == 2:
            if exp == 1:
                m = 1
            elif exp == 2:
                m = 2
            else:
                m = 2 ** (exp - 2)
        else:
            m = (p ** (exp - 1)) * (p - 1)
        lambdas.append(m)

    def lcm(a, b):
        return a * b // math.gcd(a, b)

    result = 1
    for val in lambdas:
        result = lcm(result, val)
    return result
