import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def modular_sqrt(a, p):
    if not isinstance(a, int) or not isinstance(p, int):
        raise ValueError
    if p < 3:
        raise ValueError
    if p % 2 == 0:
        raise ValueError
    if not is_prime(p):
        raise ValueError

    a = a % p
    if a == 0:
        return 0

    # Euler's criterion
    if pow(a, (p - 1) // 2, p) != 1:
        return None

    # Tonelli-Shanks algorithm
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q = Q // 2
        S += 1

    # Find quadratic non-residue
    def find_n(p):
        for n in range(2, p):
            if pow(n, (p - 1) // 2, p) == p - 1:
                return n
        return None
    n = find_n(p)

    M = S
    c = pow(n, Q, p)
    t = pow(a, Q, p)
    R = pow(a, (Q + 1) // 2, p)

    while t != 1:
        # Find the smallest i such that t^(2^i) == 1
        i, temp = 0, t
        while temp != 1:
            temp = pow(temp, 2, p)
            i += 1

        # Update variables
        M = i
        b = pow(c, 1 << (M - i - 1), p)
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

    return min(R, p - R)
