        raise ValueError("Arguments must be integers.")
    if p < 3:
        raise ValueError("p must be >= 3.")
    if p % 2 == 0:
        raise ValueError("p must be odd.")
    if not is_prime(p):
        raise ValueError("p must be a prime.")

    a = a % p
    if a == 0:
        return 0

    if pow(a, (p - 1) // 2, p) != 1:
        return None

    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    def find_nresidue(p):
        for n in range(2, p):
            if pow(n, (p - 1) // 2, p) == p - 1:
                return n
        return None

    n = find_nresidue(p)
    if n is None:
        raise ValueError("No quadratic non-residue found.")

    M = S
    c = pow(n, Q, p)
    t = pow(a, Q, p)
    R = pow(a, (Q + 1) // 2, p)

    while t != 1:
        i, temp = 0, t
        while temp != 1:
            temp = pow(temp, 2, p)
            i += 1
        if i >= M:
            raise ValueError("Unexpected failure in algorithm.")

        b = pow(c, 1 << (M - i - 1), p)
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

    return min(R, p - R)

