```python
def polygon_area(vertices):
    if not isinstance(vertices, (list, tuple)) or len(vertices) < 3:
        raise ValueError
    for i, (x, y) in enumerate(vertices):
        if not (isinstance(x, (int, float)) and not isinstance(x, bool)) or not (isinstance(y, (int, float)) and not isinstance(y, bool)):
            raise ValueError
    n = len(vertices)
    det_sum = 0.0
    for i in range(n):
        xi, yi = vertices[i]
        xj, yj = vertices[(i + 1) % n]
        det_sum += (xi * yj - xj * yi)
    area = abs(det_sum) * 0.5
    if area < 1e-9:
        raise ValueError
    return round(area, 4)

def polygon_centroid(vertices):
    if not isinstance(vertices, (list, tuple)) or len(vertices) < 3:
        raise ValueError
    for i, (x, y) in enumerate(vertices):
        if not (isinstance(x, (int, float)) and not isinstance(x, bool)) or not (isinstance(y, (int, float)) and not isinstance(y, bool)):
            raise ValueError
    n = len(vertices)
    det_sum = 0.0
    cx_sum = 0.0
    cy_sum = 0.0
    for i in range(n):
        xi, yi = vertices[i]
        xj, yj = vertices[(i + 1) % n]
        term = xi * yj - xj * yi
        det_sum += term
        cx_sum += (xi + xj) * term
        cy_sum += (yi + yj) * term
    area_signed = det_sum * 0.5
    if abs(area_signed) < 1e-9:
        raise ValueError
    cx = cx_sum / (6 * area_signed)
    cy = cy_sum / (6 * area_signed)
