For the given problem, the approach involves validating the input boxes to ensure they are correctly structured and contain valid numeric values. The intersection and union volumes are computed using geometric overlap formulas and inclusion-exclusion principles. The final numeric result is returned as an integer if exact, or rounded to 4 decimal places otherwise.

```python
def box_intersection_volume(box1, box2):
    def validate(box):
        if len(box) != 6:
            raise ValueError
        for x in box:
            if not isinstance(x, (int, float)) or isinstance(x, bool):
                raise ValueError
        xmin, ymin, zmin, xmax, ymax, zmax = box
        if xmin > xmax or ymin > ymax or zmin > zmax:
            raise ValueError

    validate(box1)
    validate(box2)

    xmin1, ymin1, zmin1, xmax1, ymax1, zmax1 = box1
    xmin2, ymin2, zmin2, xmax2, ymax2, zmax2 = box2

    dx = max(0.0, min(xmax1, xmax2) - max(xmin1, xmin2))
    dy = max(0.0, min(ymax1, ymax2) - max(ymin1, ymin2))
    dz = max(0.0, min(zmax1, zmax2) - max(zmin1, zmin2))

    volume = dx * dy * dz

    if volume.is_integer():
        return int(volume)
    else:
        return round(volume, 4)

def box_union_volume(box1, box2):
    def validate(box):
        if len(box) != 6:
            raise ValueError
        for x in box:
            if not isinstance(x, (int, float)) or isinstance(x, bool):
                raise ValueError
        xmin, ymin, zmin, xmax, ymax, zmax = box
        if xmin > xmax or ymin > ymax or zmin > zmax:
            raise ValueError

    validate(box1)
    validate(box2)

    xmin1, ymin1, zmin1, xmax1, ymax1, zmax1 = box1
    xmin2, ymin2, zmin2, xmax2, ymax2, zmax2 = box2

    vol1 = (xmax1 - xmin1) * (ymax1 - ymin1) * (zmax1 - zmin1)
    vol2 = (xmax2 - xmin2) * (ymax2 - ymin2) * (zmax2 - zmin2)
    inter_vol = box_intersection_volume(box1, box2)

    union_vol = vol1 + vol2 - inter_vol

    if union_vol.is_integer():
        return int(union_vol)
    else:
        return round(union_vol, 4)
