# Rationale
The Bellman-Ford algorithm is implemented with strict input validation to ensure correctness. It first checks that all input parameters conform to the required types and ranges. Then, it initializes distances and relaxes edges for $ n_{\text{nodes}} - 1 $ iterations. A final iteration checks for relaxable edges to detect negative-weight cycles. The distance array is converted to integers where applicable for exact values, ensuring the output format matches the requirements.

```python
def bellman_ford(n_nodes, edges, source):
    if not isinstance(n_nodes, int) or n_nodes <= 0:
        raise ValueError
    if not isinstance(source, int) or not (0 <= source < n_nodes):
        raise ValueError
    for u, v, w in edges:
        if not isinstance(u, int) or not (0 <= u < n_nodes):
            raise ValueError
        if not isinstance(v, int) or not (0 <= v < n_nodes):
            raise ValueError
        if isinstance(w, bool):
            raise ValueError
        if not isinstance(w, (int, float)):
            raise ValueError

    INF = float('inf')
    dist = [INF] * n_nodes
    dist[source] = 0.0

    for _ in range(n_nodes - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break

    has_negative_cycle = False
    for u, v, w in edges:
        if dist[u] != INF and dist[v] > dist[u] + w:
            has_negative_cycle = True
            break

    distances = []
    for d in dist:
        if d == INF:
            distances.append(float('inf'))
        elif d.is_integer():
            distances.append(int(d))
        else:
            distances.append(d)

    return (distances, has_negative_cycle)
