def max_clique(n_nodes, edges):
    # Input validation
    if not isinstance(n_nodes, int):
        raise ValueError
    if not (1 <= n_nodes <= 20):
        raise ValueError
    if not isinstance(edges, (list, tuple)):
        raise ValueError
    adjacency = [[False] * n_nodes for _ in range(n_nodes)]
    for i, (u, v) in enumerate(edges):
        if not (isinstance(u, int) and isinstance(v, int)):
            raise ValueError
        if not (0 <= u < n_nodes and 0 <= v < n_nodes):
            raise ValueError
        if u == v:
            continue  # ignore self-loops
        adjacency[u][v] = True
        adjacency[v][u] = True

    best_clique = tuple(range(n_nodes)) if n_nodes == 1 else (0,)

    def is_clique(clique, candidate):
        return all(adjacency[candidate][node] for node in clique)

    def backtrack(current, start):
        nonlocal best_clique
        if len(current) > len(best_clique):
            best_clique = tuple(sorted(current))
        for i in range(start, n_nodes):
            if is_clique(current, i):
                current.append(i)
                backtrack(current, i + 1)
                current.pop()

    for start in range(n_nodes):
        backtrack([start], start + 1)

    return tuple(sorted(best_clique))
