                raise ValueError("arrivals must contain non-negative integers")

    # Initialize simulation variables
    queue_ns = 0
    queue_ew = 0
    served_ns = 0
    served_ew = 0
    T_cycle = green_ns + yellow_time + green_ew + yellow_time

    # Simulate each time step
    for t in range(total_steps):
        # Add arrivals
        if t < len(arrivals_ns):
            queue_ns += arrivals_ns[t]
        if t < len(arrivals_ew):
            queue_ew += arrivals_ew[t]

        # Determine phase
