To solve the rod cutting problem with a fixed cutting cost per cut, we use dynamic programming (DP). The DP array `dp` stores for each length the maximum net revenue and the corresponding optimal partition. For each rod length `i`, we evaluate all possible first cuts `j`, compute the revenue by adding the price for length `j` and the previously computed optimal revenue for the remaining length `i-j`, then subtract the cost of one additional cut. If multiple partitions yield the same revenue, we select the lexicographically smallest one. This approach ensures optimal substructure and overlapping subproblems are handled efficiently.

```python
def rod_cut_with_cut_cost(length, prices, cut_cost):
    if not isinstance(length, int) or length < 0:
        raise ValueError
    if not (isinstance(prices, list) or isinstance(prices, tuple)):
        raise ValueError
    if any(not isinstance(p, (int, float)) or p < 0 for p in prices):
        raise ValueError
    if not isinstance(cut_cost, (int, float)) or cut_cost < 0:
        raise ValueError
    if length == 0:
        return (0, ())
    max_len = length
    n = len(prices)
    # dp[i] = (max_revenue, best_partition)
    dp = [ (0.0, ()) for _ in range(max_len + 1) ]
    for i in range(1, max_len + 1):
        best_rev = -float('inf')
        best_part = None
        for j in range(1, min(i, n) + 1):
            remaining = i - j
            rev = prices[j-1]
            if remaining > 0:
                rev += dp[remaining][0] - cut_cost
            if rev > best_rev:
                best_rev = rev
                part = list(dp[remaining][1]) if remaining > 0 else []
                part.append(j)
                best_part = tuple(sorted(part))
            elif rev == best_rev:
                part = list(dp[remaining][1]) if remaining > 0 else []
                part.append(j)
                candidate = tuple(sorted(part))
                if candidate < best_part:
                    best_part = candidate
        dp[i] = (best_rev, best_part)
    max_rev, cuts = dp[length]
    # Round if needed and convert to int if exact
    if max_rev.is_integer():
        max_rev = int(max_rev)
    else:
        max_rev = round(max_rev, 4)
    return (max_rev, cuts)
