            raise ValueError
        if not (isinstance(ts, (int, float)) and ts >= 0 and isinstance(cost, (int, float)) and cost >= 0):
            raise ValueError
    # Check timestamps are non-decreasing
    for i in range(1, len(requests)):
        if requests[i][0] < requests[i-1][0]:
            raise ValueError

    allowed_list = []
    tokens = float(capacity)
    last_timestamp = requests[0][0]

    # Process first request
    _, cost = requests[0]
    allowed_list.append(tokens >= cost)
    if allowed_list[0]:
        tokens -= cost

