To compute the minimum expected search cost of an optimal Binary Search Tree (BST), we use dynamic programming. The key idea is to build a table `dp[i][j]` that stores the minimum cost for keys indexed from `i` to `j`. For each range of keys, we consider all possible roots and compute the cost as the sum of left and right subtrees plus the sum of frequencies in the current range. The solution is built bottom-up for increasing lengths of key sequences, ensuring optimal substructure and overlapping subproblems are efficiently handled.

```python
def optimal_bst_cost(keys, frequencies):
    if len(keys) != len(frequencies):
        raise ValueError("Length mismatch between keys and frequencies")
    n = len(keys)
    if n == 0:
        return 0

    # Validate inputs
    for i in range(n):
        if not (isinstance(keys[i], (int, float)) and not isinstance(keys[i], bool)):
            raise ValueError("Keys must be numbers, not bool")
        if not (isinstance(frequencies[i], (int, float)) and not isinstance(frequencies[i], bool)):
            raise ValueError("Frequencies must be numbers, not bool")
        if frequencies[i] < 0:
            raise ValueError("Negative frequency not allowed")
    for i in range(1, n):
        if keys[i] <= keys[i - 1]:
            raise ValueError("Keys must be strictly increasing")

    # Prefix sum for frequencies
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + frequencies[i]

    # Initialize DP table
    dp = [[0.0] * n for _ in range(n)]

    # Fill for all lengths of sequences from 2 to n
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            dp[i][j] = float('inf')
            sum_freq = prefix[j + 1] - prefix[i]
            for r in range(i, j + 1):
                left = dp[i][r - 1] if r > i else 0.0
                right = dp[r + 1][j] if r < j else 0.0
                total = left + right + sum_freq
                if total < dp[i][j]:
                    dp[i][j] = total

    result = dp[0][n - 1]
    if result.is_integer():
        return int(result)
    else:
        return round(result, 4)
