def simulate_vending(items, coin_inventory, events):
    # Validate inputs
    if not isinstance(items, dict):
        raise ValueError("items must be a dictionary")
    for code, item in items.items():
        if not isinstance(item, dict) or 'price' not in item or 'stock' not in item:
            raise ValueError("Invalid item structure")
        price = item['price']
        stock = item['stock']
        if not (isinstance(price, int) and not isinstance(price, bool)) or price <= 0:
            raise ValueError("price must be a positive integer")
        if not (isinstance(stock, int) and not isinstance(stock, bool)) or stock <= 0:
            raise ValueError("stock must be a positive integer")

    if not isinstance(coin_inventory, dict):
        raise ValueError("coin_inventory must be a dictionary")
    for denom, count in coin_inventory.items():
        if not (isinstance(denom, int) and not isinstance(denom, bool)) or denom <= 0:
            raise ValueError("coin denominations must be positive integers")
        if not isinstance(count, int) or count < 0:
            raise ValueError("coin counts must be non-negative integers")

    for event in events:
        if not isinstance(event, tuple) or len(event) < 1:
            raise ValueError("Invalid event structure")
        if event[0] not in ("insert", "select", "return_coins"):
            raise ValueError("Invalid event type")
        if event[0] == "insert" and len(event) != 2:
            raise ValueError("Invalid insert event")
        if event[0] == "select" and len(event) != 2:
            raise ValueError("Invalid select event")
        if event[0] == "return_coins" and len(event) != 1:
            raise ValueError("Invalid return_coins event")

    event_log = []
    current_balance = 0

    for event in events:
        if event[0] == "insert":
            coin_value = event[1]
            if coin_value not in coin_inventory:
                event_log.append(("rejected_coin", coin_value))
