            else:
                prev_line = 2
        else:
            if f2[j] == f2[j-1] + line2_times[j]:
                prev_line = 2
            else:
                prev_line = 1
        line_choices[j-1] = prev_line
        current_line = prev_line

    if min_total.is_integer():
        min_total = int(min_total)
    else:
        min_total = round(min_total, 4)

    return (min_total, tuple(line_choices))

def assembly_line_schedule(line1_times, line2_times, transfer1_to_2, transfer2_to_1, entry_times, exit_times):
    n = len(line1_times)
    if n == 0:
        return (0, ())
    if len(line2_times) != n or len(transfer1_to_2) != n - 1 or len(transfer2_to_1) != n - 1 or len(entry_times) != 2 or len(exit_times) != 2:
        raise ValueError("Invalid input lengths")
    for times in [line1_times, line2_times, transfer1_to_2, transfer2_to_1]:
        for val in times:
            if val < 0:
                raise ValueError("Negative values not allowed")
    for val in entry_times + exit_times:
        if val < 0:
            raise ValueError("Negative values not allowed")

    f1 = [0] * n
    f2 = [0] * n
    f1[0] = entry_times[0] + line1_times[0]
    f2[0] = entry_times[1] + line2_times[0]

    for j in range(1, n):
        option1_1 = f1[j-1] + line1_times[j]
        option2_1 = f2[j-1] + transfer2_to_1[j-1] + line1_times[j]
        f1[j] = min(option1_1, option2_1)

        option1_2 = f2[j-1] + line2_times[j]
        option2_2 = f1[j-1] + transfer1_to_2[j-1] + line2_times[j]
        f2[j] = min(option1_2, option2_2)

    total1 = f1[-1] + exit_times[0]
    total2 = f2[-1] + exit_times[1]
    if total1 < total2:
        min_total = total1
        current_line = 1
    elif total2 < total1:
        min_total = total2
        current_line = 2
    else:
        min_total = total1
        current_line = 1  # Tie-break by preferring Line 1

    line_choices = [0] * n
    line_choices[-1] = current_line

    for j in range(n-1, 0, -1):
        if current_line == 1:
            if f1[j] == f1[j-1] + line1_times[j]:
                prev_line = 1
            else:
                prev_line = 2
        else:
            if f2[j] == f2[j-1] + line2_times[j]:
                prev_line = 2
            else:
                prev_line = 1
        line_choices[j-1] = prev_line
        current_line = prev_line

    if min_total.is_integer():
        min_total = int(min_total)
    else:
        min_total = round(min_total, 4)

    return (min_total, tuple(line_choices))

