To simulate a Connect Four game, we first validate each move and update the board accordingly. The board is represented as a 6x7 grid. For each move, we determine the next available row in the selected column by scanning from the bottom up. After placing a disk, we check for a win by examining all four possible directions (horizontal, vertical, and two diagonals) for a line of four matching disks. If a win is detected, we return the winner along with the winning line and the number of moves played. If the board fills without a win, we return a draw.

```python
def play_connect_four(moves):
    board = [['' for _ in range(7)] for _ in range(6)]
    players = ['R', 'Y']
    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]

    for move in moves:
        if not isinstance(move, int) or not (0 <= move <= 6):
            raise ValueError("Invalid move")
        col = move
        # Find next available row
        row = -1
        for r in range(6):
            if board[r][col] == '':
                row = r
                break
        if row == -1:
            raise ValueError("Column overflow")
        # Determine current player
        turn = len([m for m in moves if moves.index(m) < moves.index(move)]) % 2
        player = players[turn]
        board[row][col] = player

        # Check for win
        for dr, dc in directions:
            count = 1
            r, c = row + dr, col + dc
            while 0 <= r < 6 and 0 <= c < 7 and board[r][c] == player:
                count += 1
                r += dr
                c += dc
            r, c = row - dr, col - dc
            while 0 <= r < 6 and 0 <= c < 7 and board[r][c] == player:
                count += 1
                r -= dr
                c -= dc
            if count >= 4:
                # Find the winning coordinates
                win_coords = []
                r, c = row - dr * (count - 1), col - dc * (count - 1)
                for i in range(4):
                    win_coords.append((r + dr * i, c + dc * i))
                win_coords.sort()
                return (player, tuple(win_coords), len(moves))

    # Check if board is full
    if all(all(cell != '' for cell in row) for row in board):
        return ('draw', (), 42)
    else:
        return ('in_progress', (), len(moves))
