For the `escape_c_string` function, I use a dictionary to map special characters to their escape sequences. Each character is checked against this map, and if not present, it's either left as-is (if printable) or converted to a hex escape. For `unescape_c_string`, I iterate through the string, handling escape sequences by checking the character following a backslash and processing accordingly. Special care is taken to validate hex escapes and ensure no trailing backslash exists.

```python
def escape_c_string(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    escape_map = {
        '\n': '\\n',
        '\t': '\\t',
        '\r': '\\r',
        '\\': '\\\\',
        '"': '\\"',
        '\0': '\\0',
    }
    result = []
    for char in text:
        if char in escape_map:
            result.append(escape_map[char])
        else:
            o = ord(char)
            if 32 <= o <= 126:
                result.append(char)
            else:
                result.append(f'\\x{o:02x}')
    return ''.join(result)

def unescape_c_string(escaped):
    if not isinstance(escaped, str):
        raise ValueError("Input must be a string.")
    i = 0
    result = []
    while i < len(escaped):
        if escaped[i] == '\\':
            i += 1
            if i >= len(escaped):
                raise ValueError("Trailing backslash.")
            c = escaped[i]
            if c in {'n', 't', 'r', '\\', '"', '0'}:
                if c == 'n':
                    result.append('\n')
                elif c == 't':
                    result.append('\t')
                elif c == 'r':
                    result.append('\r')
                elif c == '\\':
                    result.append('\\')
                elif c == '"':
                    result.append('"')
                elif c == '0':
                    result.append('\0')
                i += 1
            elif c == 'x':
                if i + 2 > len(escaped):
                    raise ValueError("Incomplete \\x escape.")
                hex_part = escaped[i+1:i+3]
                try:
                    val = int(hex_part, 16)
                except ValueError:
                    raise ValueError("Invalid hex digits in escape.")
                result.append(chr(val))
                i += 3
            else:
                raise ValueError(f"Unknown escape sequence \\\\{c!r}.")
        else:
            result.append(escaped[i])
            i += 1
    return ''.join(result)
