To implement RFC 4648 Base32 encoding and decoding, the approach leverages bitwise operations and strict validation. The `b32_encode` function processes data in 5-byte chunks, converting each to 8 5-bit groups using the specified alphabet. Padding is added based on the remainder of the input length modulo 5. The `b32_decode` function validates the input length, padding, and character validity, then reconstructs the original bytes by reversing the encoding process, ensuring unused bits are zero.

```python
def b32_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("Input must be bytes or bytearray")
    if not data:
        return ""
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    bits = []
    for b in data:
        bits.extend((b >> i) & 1 for i in reversed(range(8)))
    padding_bits = (len(bits) + 4) // 5 * 5 - len(bits)
    bits.extend([0] * padding_bits)
    result = []
    for i in range(0, len(bits), 5):
        chunk = bits[i:i+5]
        index = sum(chunk[j] << j for j in range(5))
        result.append(alphabet[index])
    pad_len = (8 - (len(data) * 8 % 40) * 2) % 40 // 5 if len(data) % 5 else 0
    result[-pad_len:] = ['='] * pad_len
    return ''.join(result)

def b32_decode(text):
    if not isinstance(text, str):
        raise ValueError("Input must be str")
    text = text.upper().replace(' ', '').replace('\t', '')
    if not text:
        return b""
    valid_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZ234567=")
    if not all(c in valid_chars for c in text):
        raise ValueError("Invalid character in input")
    if len(text) % 8 != 0:
        raise ValueError("Input length must be multiple of 8")
    padding = text.rfind('=')
    if padding == -1:
        padding = len(text)
    if padding not in {0, 1, 3, 4, 6}:
        raise ValueError("Invalid padding")
    bits = []
    for c in text[:padding]:
        idx = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567".find(c)
        if idx == -1:
            raise ValueError("Invalid character in input")
        for i in reversed(range(5)):
            bits.append((idx >> i) & 1)
    if padding and len(bits) % 8 != 0:
        raise ValueError("Unused bits must be zero")
    result = []
    for i in range(0, len(bits), 8):
        byte = sum(bits[i+j] << (7-j) for j in range(8))
        result.append(byte)
    return bytes(result)
