```python
def format_nmea(body):
    if not isinstance(body, str):
        raise ValueError("body must be a string")
    if not body:
        raise ValueError("body is empty")
    for c in body:
        if ord(c) < 32 or ord(c) > 126 or c in "$!*\\r\\n":
            raise ValueError("body contains invalid characters")
    checksum = 0
    for c in body:
        checksum ^= ord(c)
    return f"${body}*{checksum:02X}\r\n"

def parse_nmea(line):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    if len(line) < 5 or line[-2:] != "\r\n":
        raise ValueError("line must end with \\r\\n")
    stripped = line[:-2]
    if not stripped or stripped[0] not in "$!":
        raise ValueError("line must start with $ or !")
    parts = stripped.split("*", 1)
    if len(parts) != 2:
        raise ValueError("invalid checksum format")
    body, chk_str = parts[0], parts[1]
    if len(chk_str) != 2 or not all(c in "0123456789abcdefABCDEF" for c in chk_str):
        raise ValueError("invalid checksum format")
    if any(c in body for c in "$!*"):
        raise ValueError("body contains invalid characters")
    computed = 0
    for c in body:
        computed ^= ord(c)
    expected = int(chk_str, 16)
    if computed != expected:
        raise ValueError("checksum mismatch")
    return body
