For the Roman numeral conversion functions, we use a structured approach to ensure correctness and validation. The `to_roman` function maps integers to Roman numerals using a predefined list of value-symbol pairs in descending order, applying subtractive notation as required. The `from_roman` function validates the input string by checking for valid characters, canonical structure, and ensures that parsed values align with the standard subtractive rules and range constraints.

```python
def to_roman(val):
    if not isinstance(val, int) or not (1 <= val <= 3999):
        raise ValueError
    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    res = []
    for value, symbol in roman_numerals:
        while val >= value:
            res.append(symbol)
            val -= value
    return ''.join(res)

def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError
    valid_chars = set('IVXLCDM')
    if not all(c in valid_chars for c in s):
        raise ValueError
    roman_to_int = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
    allowed_pairs = {('I', 'V'), ('I', 'X'), ('X', 'L'), ('X', 'C'), ('C', 'D'), ('C', 'M')}
    total = 0
    prev_value = 0
    for i in reversed(range(len(s))):
        current = s[i]
        current_val = roman_to_int[current]
        if i > 0:
            next_char = s[i-1]
            next_val = roman_to_int[next_char]
            if next_val < current_val and (next_char, current) not in allowed_pairs:
                raise ValueError
        if current_val < prev_value:
            total -= current_val
        else:
