The original `from_roman` function had two critical flaws: (1) it only checked adjacent pairs for subtractive validity, failing to reject non-canonical sequences like "IIV"; and (2) its logic for validating pairs was flawed due to incorrect index traversal. The corrected solution introduces a stateful parsing approach using a lookup table of valid subtractive pairs and ensures each character is processed in order, checking for invalid sequences at every step.

```python
def to_roman(val):
    if not isinstance(val, int) or not (1 <= val <= 3999):
        raise ValueError
    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    res = []
    for value, symbol in roman_numerals:
        while val >= value:
            res.append(symbol)
            val -= value
    return ''.join(res)

def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError
    valid_chars = set('IVXLCDM')
    if not all(c in valid_chars for c in s):
        raise ValueError
    roman_to_int = {'I':1, 'V':5, 'X':10, 'L':50, 'C':100, 'D':500, 'M':1000}
