            total += roman_to_int[s[i+1]] - roman_to_int[s[i]]
            i += 2
        else:
            total += roman_to_int[s[i]]
            i += 1
    if not (1 <= total <= 3999) or to_roman(total) != s:
        raise ValueError
    return total
