For the encoding function, the ZigZag transformation maps signed integers to unsigned integers, allowing efficient varint encoding. The varint encoding uses 7-bit chunks with continuation bits. For decoding, we accumulate 7-bit chunks until the continuation bit is clear, then apply the inverse ZigZag transformation.

```python
def encode_zigzag_varint(val):
    if type(val) is not int:
        raise ValueError("val must be an int")
    if val >= 0:
        z = val << 1
    else:
        z = (val << 1) + 1
    bytes_list = []
    while True:
        bytes_list.append(z & 0x7F)
        z >>= 7
        if z == 0:
            break
    # Set continuation bits
    for i in range(len(bytes_list) - 1):
        bytes_list[i] |= 0x80
    return bytes(bytes_list)

def decode_zigzag_varint(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")
    if not data:
        raise ValueError("data is empty")
    val = 0
    consumed = 0
    for byte in data:
        consumed += 1
        val = (val << 7) | (byte & 0x7F)
        if not (byte & 0x80):
            break
    else:
        raise ValueError("incomplete varint")
    if val & 1:
        val = -(val >> 1) - 1
    else:
        val >>= 1
    return (val, consumed)
```

