def b58_encode(data):
    ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("Input must be bytes or bytearray")
    if not data:
        return ""
    leading_zeros = 0
    while leading_zeros < len(data) and data[leading_zeros] == 0:
        leading_zeros += 1
    num = int.from_bytes(data[leading_zeros:], 'big') if data[leading_zeros:] else 0
    encoded = ''
    while num > 0:
        num, rem = divmod(num, 58)
        encoded = ALPHABET[rem] + encoded
    result = (ALPHABET[0] * leading_zeros) + encoded
    return result

def b58_decode(text):
    ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
    if not isinstance(text, str):
        raise ValueError("Input must be str")
    if not text:
        return b""
    leading_ones = 0
    while leading_ones < len(text) and text[leading_ones] == '1':
        leading_ones += 1
    value = 0
    for char in text[leading_ones:]:
        if char not in ALPHABET:
            raise ValueError("Invalid character in Base58 string")
        value = value * 58 + ALPHABET.index(char)
    if value == 0:
        result = b'\x00' * leading_ones
    else:
        result = value.to_bytes((value.bit_length() + 7) // 8, 'big')
        result = b'\x00' * leading_ones + result
    return result
