def uuid_to_urn(uuid_bytes):
    if not isinstance(uuid_bytes, (bytes, bytearray)):
        raise ValueError("Input must be bytes or bytearray")
    if len(uuid_bytes) != 16:
        raise ValueError("Input must be exactly 16 bytes")
    hex_str = uuid_bytes.hex()
    return f"urn:uuid:{hex_str[:8]}-{hex_str[8:12]}-{hex_str[12:16]}-{hex_str[16:20]}-{hex_str[20:]}"

def urn_to_uuid(urn_str):
    if not isinstance(urn_str, str):
        raise ValueError("Input must be a string")
    prefix = "urn:uuid:"
    if urn_str[:9].lower() != prefix:
        raise ValueError("Invalid URN prefix")
    s_part = urn_str[9:]
    if len(s_part) != 36:
        raise ValueError("Invalid UUID length")
    if s_part[8] != '-' or s_part[13] != '-' or s_part[18] != '-' or s_part[23] != '-':
        raise ValueError("Invalid hyphen positions")
    clean = s_part.replace('-', '').lower()
    try:
        return bytes.fromhex(clean)
    except ValueError:
        raise ValueError("Invalid hexadecimal characters")
