To implement the Intel HEX formatting and parsing functions, we ensure strict type and value validation for input parameters and records. The `format_ihex` function validates the address and record type as integers (excluding booleans), confirms the data is within length constraints, computes the checksum using two’s complement arithmetic, and formats the output as an uppercase Intel HEX string. The `parse_ihex` function strips trailing whitespace, validates the structure of the input string, extracts and validates the checksum and byte count, and returns the parsed record as a tuple.

```python
def format_ihex(address, record_type, data):
    if not isinstance(address, int) or isinstance(address, bool):
        raise ValueError("address must be int, not bool")
    if not (0 <= address <= 0xFFFF):
        raise ValueError("address out of range")
    if not isinstance(record_type, int) or isinstance(record_type, bool):
        raise ValueError("record_type must be int, not bool")
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")
    if not (0 <= len(data) <= 0xFF):
        raise ValueError("data length out of range")

    sum_val = len(data) + (address >> 8) + (address & 0xFF) + record_type
    sum_val += sum(data)
    checksum = (-sum_val) & 0xFF
    data_hex = data.hex().upper()
    return f":{len(data):02X}{address:04X}{record_type:02X}{data_hex}{checksum:02X}\n"

def parse_ihex(record_str):
    if not isinstance(record_str, str):
        raise ValueError("record_str must be a string")
    record_str = record_str.rstrip('\r\n')
    if not record_str.startswith(':'):
        raise ValueError("record must start with ':'")
    hex_data = record_str[1:]
    if len(hex_data) % 2 != 0:
        raise ValueError("hex data length must be even")
    if len(hex_data) < 10:
        raise ValueError("record too short")

    try:
        bytes_all = bytes.fromhex(hex_data)
    except ValueError:
        raise ValueError("invalid hex digits")

    ll = bytes_all[0]
    address = (bytes_all[1] << 8) | bytes_all[2]
    record_type = bytes_all[3]
    data = bytes_all[4:-1]

    if ll != len(data):
        raise ValueError("byte count mismatch")

    total_sum = sum([ll, bytes_all[1], bytes_all[2], record_type] + list(data) + [bytes_all[-1]])
    if (total_sum & 0xFF) != 0:
        raise ValueError("checksum failed")

    return (address, record_type, data)
