The implementation uses regex to validate and extract semantic version components. The `parse_semver` function validates format compliance, checks numeric parts for leading zeros, and verifies prerelease identifiers against SemVer rules. `compare_semver` follows precedence rules by comparing numeric parts first, then prerelease identifiers with custom logic for numeric vs. lexical comparison. The code handles edge cases like leading zeros and identifier types while maintaining efficiency through tuple comparisons.

```python
import re

def parse_semver(v_str):
    if not isinstance(v_str, str):
        raise ValueError("Input must be a string")

    semver_re = re.compile(
        r'^'
        r'(?P<major>\d+)'
        r'\.'
        r'(?P<minor>\d+)'
        r'\.'
        r'(?P<patch>\d+)'
        r'(?:-(?P<prerelease>[0-9A-Za-z-]+))?'
        r'(?:\+(?P<build>[0-9A-Za-z-]+))?'
        r'$'
    )
    match = semver_re.match(v_str)
    if not match:
        raise ValueError(f"Invalid semantic version format: {v_str}")

    major, minor, patch = match.groups()[:3]

    # Validate numeric parts for leading zeros
    for num_str, name in [(major, "major"), (minor, "minor"), (patch, "patch")]:
        if len(num_str) > 1 and num_str[0] == '0':
            raise ValueError(f"Invalid leading zero in {name} version: {v_str}")

    # Convert to integers
    major, minor, patch = int(major), int(minor), int(patch)

    # Process prerelease
    prerelease_str = match.group('prerelease')
    if prerelease_str:
        prerelease_ids = prerelease_str.split('.')
        for ident in prerelease_ids:
            if not ident or not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                raise ValueError(f"Invalid prerelease identifier: {v_str}")
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Invalid numeric prerelease identifier with leading zero: {v_str}")
    else:
        prerelease_ids = []

    # Process build
    build_str = match.group('build')
    if build_str:
        build_ids = build_str.split('.')
        for ident in build_ids:
            if not ident or not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                raise ValueError(f"Invalid build identifier: {v_str}")
    else:
        build_ids = []

    return (major, minor, patch, tuple(prerelease_ids), tuple(build_ids))

def compare_semver(v1_str, v2_str):
    v1 = parse_semver(v1_str)
    v2 = parse_semver(v2_str)

    # Compare numeric parts
    if v1[:3] != v2[:3]:
        return 1 if v1[:3] > v2[:3] else -1

    # If one has prerelease and the other doesn't
    if not v1[3] and v2[3]:
        return 1
    if v1[3] and not v2[3]:
        return -1

    # Compare prerelease identifiers
    p1, p2 = v1[3], v2[3]
    min_len = min(len(p1), len(p2))

    for i in range(min_len):
        id1, id2 = p1[i], p2[i]
        # Check if identifiers are numeric
        num1 = id1.isdigit()
        num2 = id2.isdigit()

        if num1 and num2:
            # Both numeric, compare as integers
            if int(id1) != int(id2):
                return 1 if int(id1) > int(id2) else -1
        elif num1:
            # Numeric < non-numeric
            return -1
        elif num2:
            # Non-numeric > numeric
            return 1
        else:
            # Both non-numeric, compare lexically
            if id1 != id2:
                return 1 if id1 > id2 else -1

    # If all compared identifiers are equal, longer one is greater
    if len(p1) != len(p2):
        return 1 if len(p1) > len(p2) else -1

    return 0
