For `encode_tsv_row`, each field is validated to be a string, then escaped by replacing `\` → `\\`, `\t` → `\\t`, `\n` → `\\n`, and `\r` → `\\r`. Fields are joined with literal `\t`. For `parse_tsv_row`, the line is split on `\t`, and each field is unescaped by scanning for valid escape sequences (`\\t`, `\\n`, `\\r`, `\\\\`). Invalid sequences or trailing backslashes raise `ValueError`.

```python
def encode_tsv_row(fields):
    if not all(isinstance(f, str) for f in fields):
        raise ValueError("All items must be strings")
    escaped_fields = []
    for field in fields:
        field = field.replace("\\", "\\\\")
        field = field.replace("\t", "\\t")
        field = field.replace("\n", "\\n")
        field = field.replace("\r", "\\r")
        escaped_fields.append(field)
    return "\t".join(escaped_fields)

def parse_tsv_row(line):
    if not isinstance(line, str):
        raise ValueError("Input must be a string")
    fields = line.split("\t")
    result = []
    for field in fields:
        i = 0
        unescaped = []
        while i < len(field):
            if field[i] != "\\":
                unescaped.append(field[i])
                i += 1
            else:
                i += 1
                if i >= len(field):
                    raise ValueError("Trailing backslash in field")
                c = field[i]
                if c in "tnr\\":
                    if c == "t":
                        unescaped.append("\t")
                    elif c == "n":
                        unescaped.append("\n")
                    elif c == "r":
                        unescaped.append("\r")
                    elif c == "\\":
                        unescaped.append("\\")
                    i += 1
                else:
                    raise ValueError(f"Unknown escape sequence '\\{c}'")
        result.append("".join(unescaped))
    return result
