def pack_coap_option(last_opt_num, opt_num, opt_value):
    if not isinstance(last_opt_num, int) or not isinstance(opt_num, int):
        raise ValueError("last_opt_num and opt_num must be non-negative integers")
    if isinstance(last_opt_num, bool) or isinstance(opt_num, bool):
        raise ValueError("last_opt_num and opt_num must be non-negative integers")
    if last_opt_num < 0 or opt_num < 0:
        raise ValueError("last_opt_num and opt_num must be non-negative")
    if opt_num < last_opt_num:
        raise ValueError("opt_num must be >= last_opt_num")
    if not isinstance(opt_value, (bytes, bytearray)):
        raise ValueError("opt_value must be bytes or bytearray")

    delta = opt_num - last_opt_num
    length = len(opt_value)

    def encode_val(val):
        if val > 65804:
            raise ValueError("Value exceeds maximum allowed (65804)")
        if val == 15:
            raise ValueError("Value 15 is reserved for payload marker")
        if val <= 12:
            return (val, b'')
        elif val <= 268:
            return (13, (val - 13).to_bytes(1, 'big'))
        else:  # 269 <= val <= 65804
            return (14, (val - 269).to_bytes(2, 'big'))

    delta_nibble, delta_ext = encode_val(delta)
    length_nibble, length_ext = encode_val(length)

    header = (delta_nibble << 4) | length_nibble
    return bytes([header]) + delta_ext + length_ext + opt_value

def unpack_coap_option(last_opt_num, data):
    if not isinstance(last_opt_num, int):
        raise ValueError("last_opt_num must be a non-negative integer")
    if last_opt_num < 0:
        raise ValueError("last_opt_num must be non-negative")
    if not data:
        raise ValueError("data is empty")

    header_byte = data[0]
    delta_nibble = (header_byte & 0xF0) >> 4
    length_nibble = header_byte & 0x0F

    if delta_nibble == 15 or length_nibble == 15:
        raise ValueError("Reserved value (15) encountered")

    def decode_val(nibble, pos):
        if nibble <= 12:
            return (nibble, pos)
        elif nibble == 13:
            if pos + 1 > len(data):
                raise ValueError("Truncated data")
            ext = data[pos]
            return (13 + ext, pos + 1)
        else:  # nibble == 14
            if pos + 2 > len(data):
                raise ValueError("Truncated data")
            ext = int.from_bytes(data[pos:pos+2], 'big')
            return (269 + ext, pos + 2)

    delta, pos = decode_val(delta_nibble, 1)
    length, pos = decode_val(length_nibble, pos)

    if pos + length > len(data):
        raise ValueError("Truncated data")

    opt_value = data[pos:pos+length]
    bytes_consumed = 1 + (pos - 1) - 1 + length  # Simplified to (pos - 1) + length
    opt_num = last_opt_num + delta

