To implement the Lucas-Lehmer test for Mersenne primes, the function first validates the input `p` to ensure it is an integer, not a boolean, and an odd prime greater than or equal to 3. A helper function `is_prime` performs a trial-division primality check. The Lucas-Lehmer recurrence is then computed modulo $ M_p = 2^p - 1 $, iterating $ p - 2 $ times. The final result is whether the last term of the sequence is zero modulo $ M_p $.

```python
def lucas_lehmer_mersenne(p):
    if not isinstance(p, int) or isinstance(p, bool):
        raise ValueError
    if p < 3:
        raise ValueError
    if p % 2 == 0:
        raise ValueError
    if not is_prime(p):
        raise ValueError
    m_p = (1 << p) - 1
    s = 4
    for _ in range(p - 2):
        s = (s * s - 2) % m_p
    return s == 0

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_div = int(n ** 0.5) + 1
    for i in range(3, max_div, 2):
        if n % i == 0:
            return False
    return True
