To solve a system of modular linear congruences where moduli are not necessarily pairwise coprime, we iteratively combine congruences using the extended Euclidean algorithm. At each step, we check for consistency and compute a new combined congruence with a modulus equal to the least common multiple (LCM) of the previous moduli. If at any point the system is inconsistent, we return `None`. Otherwise, we continue until all congruences are merged, yielding the unique solution modulo the final LCM.

```python
import math
from math import gcd

def solve_congruence_system(remainders, moduli):
    if not (isinstance(remainders, (list, tuple)) and isinstance(moduli, (list, tuple))):
        raise ValueError("Inputs must be sequences")
    if len(remainders) != len(moduli) or len(remainders) == 0:
        raise ValueError("Input sequences must be non-empty and of equal length")
    for r, m in zip(remainders, moduli):
        if not (isinstance(r, int) and isinstance(m, int)):
            raise ValueError("All elements must be integers")
        if m <= 0:
            raise ValueError("All moduli must be positive")
        if not (0 <= r < m):
            raise ValueError("Each remainder must satisfy 0 <= r < m")

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x1, y1 = extended_gcd(b, a % b)
            x = y1
            y = x1 - (a // b) * y1
            return (g, x, y)

    def mod_inverse(a, m):
        g, x, y = extended_gcd(a, m)
        if g != 1:
            return None
        else:
            return x % m

    def combine_congruences(a, m, b, n):
        d = b - a
        g = gcd(m, n)
        if d % g != 0:
            return None
        m_prime = m // g
        n_prime = n // g
        d_prime = d // g
        inv = mod_inverse(m_prime, n_prime)
        if inv is None:
            return None
        k0 = (d_prime * inv) % n_prime
        new_a = a + k0 * m
        new_m = m * n // g
        return (new_a % new_m, new_m)

    current_a, current_m = remainders[0], moduli[0]
    for i in range(1, len(remainders)):
        next_a, next_m = remainders[i], moduli[i]
        result = combine_congruences(current_a, current_m, next_a, next_m)
        if result is None:
            return None
        current_a, current_m = result
    return (current_a, current_m)
