To compute the number and sum of positive divisors of an integer $ n $, we use the prime factorization method. For $ n = p_1^{e_1} \cdots p_k^{e_k} $, the number of divisors is $ \sigma_0(n) = \prod_{i=1}^k (e_i + 1) $, and the sum of divisors is $ \sigma_1(n) = \prod_{i=1}^k \frac{p_i^{e_i + 1} - 1}{p_i - 1} $. We validate inputs to ensure $ n $ is an integer $ \geq 1 $, avoiding booleans and invalid types. Prime factorization is performed using trial division, which is efficient enough for the given constraints.

```python
import math

def divisor_count(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError
    if n == 1:
        return 1
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    i = 3
    max_factor = math.isqrt(n)
    while i <= max_factor and n > 1:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
            max_factor = math.isqrt(n)
        i += 2
    if n > 1:
        factors[n] = 1
    result = 1
    for exp in factors.values():
        result *= (exp + 1)
    return result

def divisor_sum(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError
    if n == 1:
        return 1
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    i = 3
    max_factor = math.isqrt(n)
    while i <= max_factor and n > 1:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
            max_factor = math.isqrt(n)
        i += 2
    if n > 1:
        factors[n] = 1
    result = 1
    for p, exp in factors.items():
        result *= (p ** (exp + 1) - 1) // (p - 1)
    return result
