The Stern-Brocot tree functions use mediant operations to navigate between fractions. `stern_brocot_path` constructs the path by iteratively comparing the target fraction with the mediant of current boundaries, adjusting the bounds accordingly. `stern_brocot_fraction` reconstructs the fraction by applying the path to update left/right boundaries and computing the final mediant. Both functions validate inputs to ensure correctness.

```python
def stern_brocot_path(num, den):
    if not (isinstance(num, int) and isinstance(den, int)):
        raise ValueError("Inputs must be integers")
    if num <= 0 or den <= 0:
        raise ValueError("Inputs must be positive")
    path = ""
    nL, dL = 0, 1
    nR, dR = 1, 0
    while True:
        nM = nL + nR
        dM = dL + dR
        if num * dM == den * nM:
            return path
        if num * dM < den * nM:
            path += 'L'
            dL, dR = dL, dM
            nL, nR = nL, nM
        else:
            path += 'R'
            dL, dR = dM, dR
            nL, nR = nM, nR

def stern_brocot_fraction(path):
    if not isinstance(path, str):
        raise ValueError("Path must be a string")
    if any(c not in 'LR' for c in path):
        raise ValueError("Path contains invalid characters")
    nL, dL = 0, 1
    nR, dR = 1, 0
    for c in path:
        nM = nL + nR
        dM = dL + dR
        if c == 'L':
            nR, dR = nM, dM
        else:
            nL, dL = nM, dM
    return (nL + nR, dL + dR)
