def comb_mod_prime(n, k, p):
    # Input validation
    if not all(isinstance(x, int) for x in [n, k, p]):
        raise ValueError
    if n < 0 or k < 0 or p < 2:
        raise ValueError
    if p == 2:
        is_prime = True
    else:
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
    if not is_prime:
        raise ValueError

    if k > n:
        return 0

    def get_digits(x, base):
        if x == 0:
            return [0]
        digits = []
        while x > 0:
            digits.append(x % base)
            x = x // base
        return digits

    n_digits = get_digits(n, p)
    k_digits = get_digits(k, p)

    # Pad the shorter digit list with leading zeros
    max_len = max(len(n_digits), len(k_digits))
    n_digits += [0] * (max_len - len(n_digits))
    k_digits += [0] * (max_len - len(k_digits))

    result = 1
    for ni, ki in zip(n_digits, k_digits):
        if ni < ki:
            return 0
        # Compute C(ni, ki) mod p
        # Since ni and ki are less than p, we can compute directly
        if ki > ni // 2:
            # Use symmetry to reduce computation
            ki = ni - ki
        numerator = 1
        denominator = 1
        for i in range(ki):
            numerator = numerator * (ni - i) % p
            denominator = denominator * (ki - i) % p
        inv_denominator = pow(denominator, p - 2, p)
        comb = (numerator * inv_denominator) % p
        result = (result * comb) % p

    return result
