import math

def multiplicative_order(a, n):
    if type(a) is not int or type(n) is not int:
        raise ValueError
    if n <= 1:
        raise ValueError
    a_mod = a % n
    if math.gcd(a_mod, n) != 1:
        return None
    def compute_phi(m):
        result = m
        i = 2
        while i * i <= m:
            if m % i == 0:
                while m % i == 0:
                    m //= i
                result -= result // i
            i += 1
        if m > 1:
            result -= result // m
        return result
    phi = compute_phi(n)
    def get_divisors(m):
        divisors = set()
        for i in range(1, int(m**0.5) + 1):
            if m % i == 0:
                divisors.add(i)
                divisors.add(m // i)
        return sorted(divisors)
    divisors = get_divisors(phi)
    for d in divisors:
        if pow(a_mod, d, n) == 1:
            return d
    return None
