```python
def liouville_lambda(n):
    if type(n) is not int:
        raise ValueError
    if n < 1:
        raise ValueError
    if n == 1:
        return 1
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            count += 1
            n //= i
        i += 2
    if n > 1:
        count += 1
    return 1 if count % 2 == 0 else -1

def liouville_sum(n):
    if type(n) is not int:
        raise ValueError
    if n < 1:
        raise ValueError
    total = 0
    for k in range(1, n + 1):
        total += liouville_lambda(k)
    return total
```

