def factorial_mod_prime(n, p):
    if not isinstance(n, int) or not isinstance(p, int):
        raise ValueError
    if n < 0 or p < 2:
        raise ValueError
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True
    if not is_prime(p):
        raise ValueError
    if n >= p:
        return 0
    if n == 0 or n == 1:
        return 1
    if n <= p // 2:
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % p
        return result
    else:
        # Use Wilson's theorem
        prod = 1
        for k in range(n + 1, p):
            prod = (prod * k) % p
        inv_prod = pow(prod, p - 2, p)
        return (-inv_prod) % p
