To compute Ramanujan's sum $ c_q(n) $, we use the arithmetic formula involving the Möbius function $ \mu $ and Euler's totient function $ \phi $. The function first validates inputs, computes $ d = \gcd(q, n) $, and derives $ k = q/d $. The result is calculated as $ \mu(k) \cdot \phi(q) / \phi(k) $, leveraging helper functions for $ \mu $ and $ \phi $, which rely on prime factorization via trial division.

```python
def ramanujan_sum(q, n):
    if type(q) is not int or type(n) is not int:
        raise ValueError("Inputs must be integers.")
    if q < 1 or n < 0:
        raise ValueError("q must be >=1 and n >=0.")

    def prime_factors(n):
        factors = {}
        while n % 2 == 0:
            factors[2] = factors.get(2, 0) + 1
            n //= 2
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                n //= i
            i += 2
        if n > 1:
            factors[n] = 1
        return factors

    def mobius(n):
        factors = prime_factors(n)
        for exp in factors.values():
            if exp > 1:
                return 0
        return (-1) ** len(factors)

    def totient(n):
        if n == 1:
            return 1
        result = n
        i = 2
        while i * i <= n:
            if n % i == 0:
                while n % i == 0:
                    n //= i
                result -= result // i
            i += 1
        if n > 1:
            result -= result // n
        return result

    d = gcd(q, n)
    k = q // d
    mu_val = mobius(k)
    phi_q = totient(q)
    phi_k = totient(k)
    return mu_val * phi_q // phi_k

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
