To implement the Engel expansion functions, the `to_engel_expansion` function iteratively computes each term using the ceiling formula and updates the remaining fraction until it reaches zero. The `from_engel_expansion` function reconstructs the rational number by evaluating the nested sum in reverse, ensuring the result is in its reduced form using the greatest common divisor.

```python
from math import gcd
from functools import reduce

def to_engel_expansion(num, den):
    terms = []
    current_num = num
    current_den = den
    while True:
        a_i = (current_den + current_num - 1) // current_num
        terms.append(a_i)
        new_num = current_num * a_i - current_den
        if new_num == 0:
            break
        current_num, current_den = new_num, current_den
    return terms

def from_engel_expansion(terms):
    if not terms:
        raise ValueError
    for i in range(1, len(terms)):
        if terms[i] < terms[i - 1]:
            raise ValueError
    if any(t <= 0 for t in terms):
        raise ValueError
    numerator = 1
    denominator = terms[-1]
    for term in reversed(terms[:-1]):
        numerator, denominator = denominator, numerator * term + denominator
    common = gcd(numerator, denominator)
    return (numerator // common, denominator // common)
