def convex_hull_2d(points):
    # Input validation
    if not isinstance(points, (list, tuple)):
        raise ValueError
    unique_set = set()
    cleaned_points = []
    for i, p in enumerate(points):
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            raise ValueError
        x, y = p
        for coord in [x, y]:
            if isinstance(coord, bool):
                raise ValueError
            if not isinstance(coord, (int, float)):
                raise ValueError
        if (x, y) in unique_set:
            continue
        unique_set.add((x, y))
        cleaned_points.append((x, y))
    if len(cleaned_points) < 3:
        raise ValueError

    # Sort and remove duplicates
    sorted_points = sorted(cleaned_points, key=lambda p: (p[0], p[1]))
    unique_points = []
    for p in sorted_points:
        if unique_points and p == unique_points[-1]:
            continue
        unique_points.append(p)
    if len(unique_points) < 3:
        raise ValueError

    # Cross product function
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower and upper hulls
    lower = []
    for p in unique_points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(unique_points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Combine and remove duplicates
    full_hull = lower + upper[1:-1]

    # Format output
    result = []
    for x, y in full_hull:
        x_val = int(x) if x == int(x) else round(float(x), 4)
        y_val = int(y) if y == int(y) else round(float(y), 4)
        result.append((x_val, y_val))

    return result
