        # Add unique points
        if (x, y) in unique_set:
            continue
        unique_set.add((x, y))
        cleaned_points.append((x, y))

    # Check minimum points after deduplication
    if len(cleaned_points) < 3:
        raise ValueError("Insufficient points for convex hull")

    # Sort lexicographically and remove duplicates
    sorted_points = sorted(cleaned_points, key=lambda p: (p[0], p[1]))
    unique_points = []
    for p in sorted_points:
        if unique_points and p == unique_points[-1]:
            continue
        unique_points.append(p)

    if len(unique_points) < 3:
        raise ValueError("Insufficient unique points for convex hull")

    # Cross product function
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower and upper hulls
    lower = []
    for p in unique_points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(unique_points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Combine hulls and remove duplicates
    full_hull = lower[:-1] + upper[:-1]

    # Check for degenerate hull
    if len(full_hull) < 3:
        raise ValueError("Degenerate convex hull")

    # Check for collinearity
