            raise ValueError("vertices must be integers")
        if not (0 <= u < n_nodes) or not (0 <= v < n_nodes):
            raise ValueError("vertex index out of range")
    adj = [[] for _ in range(n_nodes)]
    for u, v in edges:
        adj[u].append(v)
    disc = [-1] * n_nodes
    low = [-1] * n_nodes
    time = [0]
    stack = []
    on_stack = [False] * n_nodes
    sccs = []

    def strongconnect(v):
        disc[v] = low[v] = time[0]
        time[0] += 1
        stack.append(v)
        on_stack[v] = True
        for w in adj[v]:
            if disc[w] == -1:
                strongconnect(w)
                low[v] = min(low[v], low[w])
            elif on_stack[w]:
                low[v] = min(low[v], disc[w])
        if low[v] == disc[v]:
            component = []
            while True:
                node = stack.pop()
                component.append(node)
                on_stack[node] = False
                if node == v:
                    break
            sccs.append(tuple(sorted(component)))

    for node in range(n_nodes):
        if disc[node] == -1:
            strongconnect(node)
    sccs.sort()
    return sccs
