Kruskal's algorithm efficiently finds the MST by sorting edges and using DSU to avoid cycles. The edges are filtered for self-loops, validated for correct types and ranges, then sorted by weight and canonical form. DSU with path compression and union by rank ensures efficient connectivity checks. Chosen edges are collected, and the total weight is formatted as required.

```python
def kruskal_mst(n_nodes, edges):
    if not isinstance(n_nodes, int) or isinstance(n_nodes, bool):
        raise ValueError("n_nodes must be a non-negative integer")
    if n_nodes < 0:
        raise ValueError("n_nodes must be non-negative")
    if n_nodes == 0:
        return (0, [])

    filtered_edges = []
    for u, v, w in edges:
        if not isinstance(u, int) or isinstance(u, bool):
            raise ValueError("u must be an integer")
        if not isinstance(v, int) or isinstance(v, bool):
            raise ValueError("v must be an integer")
        if u < 0 or u >= n_nodes or v < 0 or v >= n_nodes:
            raise ValueError("vertex index out of range")
        if not isinstance(w, (int, float)) or isinstance(w, bool):
            raise ValueError("weight must be a real number")
        if u != v:
            filtered_edges.append((u, v, w))

    class DSU:
        def __init__(self, size):
            self.parent = list(range(size))
            self.rank = [0] * size
        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]
        def union(self, x, y):
            xroot = self.find(x)
            yroot = self.find(y)
            if xroot == yroot:
                return False
            if self.rank[xroot] < self.rank[yroot]:
                self.parent[xroot] = yroot
            else:
                self.parent[yroot] = xroot
                if self.rank[xroot] == self.rank[yroot]:
                    self.rank[xroot] += 1
            return True

    sorted_edges = sorted(filtered_edges, key=lambda e: (e[2], (min(e[0], e[1]), max(e[0], e[1]))))
    dsu = DSU(n_nodes)
    chosen_edges = []
    total = 0.0

    for u, v, w in sorted_edges:
        if dsu.union(dsu.find(u), dsu.find(v)):
            chosen_edges.append((min(u, v), max(u, v)))
            total += w

    if total == int(total):
        total_weight = int(total)
    else:
        total_weight = round(total, 4)

    return (total_weight, sorted(chosen_edges))
```

