The original code incorrectly flagged points with near-zero cross products as being on the boundary, even when they were slightly inside. This happened because the cross product tolerance (`1e-9`) was too lenient, leading to false boundary detections. The fix involves ensuring that a cross product near zero is only considered part of the boundary if the point lies *exactly on the line segment*, not just near it. This is achieved by checking if the point's projection onto the edge lies within the segment's parameter range (`0 ≤ t ≤ 1`), not just the bounding box.

```python
def point_in_convex_poly(point, vertices):
    # Input validation
    if not isinstance(point, (list, tuple)) or len(point) != 2:
        raise ValueError()
    if any(not isinstance(x, (int, float)) for x in point):
        raise ValueError()
    if not isinstance(vertices, (list, tuple)) or len(vertices) < 3:
        raise ValueError()
    for v in vertices:
        if not isinstance(v, (list, tuple)) or len(v) != 2:
            raise ValueError()
        if any(isinstance(x, bool) for x in v):
            raise ValueError()

    # Process each edge
    n = len(vertices)
    boundary_found = False

    for i in range(n):
        xi, yi = vertices[i]
        xj, yj = vertices[(i + 1) % n]

        dx = xj - xi
        dy = yj - yi
        cross = dx * (point[1] - yi) - dy * (point[0] - xi)

        if cross < -1e-9:
            return "outside"
        elif abs(cross) <= 1e-9:
            # Check if point lies on the segment
            # Compute projection parameter t
            seg_len_sq = dx*dx + dy*dy
            if seg_len_sq < 1e-18:  # Edge is a point
                continue  # Skip, handled by other edges
            t = ((point[0] - xi)*dx + (point[1] - yi)*dy) / seg_len_sq
            if 0 <= t <= 1:
                boundary_found = True

    if boundary_found:
        return "boundary"
    else:
        return "inside"
