To solve this problem, we implement Dijkstra's algorithm with a min-heap and lexicographical tie-breaking. The algorithm first validates all inputs to ensure correctness. It initializes distances and paths for each node, using the heap to prioritize nodes by distance and path lexicography. For each node processed, it relaxes edges, updating distances and paths when shorter paths are found or when equal distances require lexicographical comparison. The path is reconstructed using predecessors once the target is reached.

```python
import heapq
import math

def dijkstra_shortest_path(n_nodes, edges, source, target):
    # Validate input types and values
    if not isinstance(n_nodes, int) or n_nodes <= 0:
        raise ValueError("Invalid n_nodes")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("Invalid edges")
    for u, v, w in edges:
        if not (isinstance(u, int) and isinstance(v, int) and isinstance(w, (int, float))):
            raise ValueError("Invalid edge")
        if not (0 <= u < n_nodes and 0 <= v < n_nodes):
            raise ValueError("Invalid vertex index")
        if w < 0:
            raise ValueError("Negative weight")
    if not (isinstance(source, int) and isinstance(target, int)):
        raise ValueError("Invalid source or target")
    if not (0 <= source < n_nodes and 0 <= target < n_nodes):
        raise ValueError("Invalid source or target")

    # Initialize distance and path tracking
    INF = math.inf
    dist = [INF] * n_nodes
    path = [None] * n_nodes
    prev = [None] * n_nodes
    dist[source] = 0
    path[source] = [source]

    # Priority queue: (distance, path, node)
    heap = [(0.0, [source], source)]

    while heap:
        current_dist, current_path, u = heapq.heappop(heap)
        if u == target:
            break
        if current_dist > dist[u]:
            continue  # Skip outdated entries
        for u, v, w in edges:
            if u == u:  # Only process outgoing edges from u
                new_dist = current_dist + w
                new_path = current_path + [v]
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    path[v] = new_path
                    prev[v] = u
                    heapq.heappush(heap, (new_dist, new_path, v))
                elif math.isclose(new_dist, dist[v], rel_tol=1e-9, abs_tol=1e-9):
                    # Check lexicographical order
                    if path[v] is None or tuple(new_path) < tuple(path[v]):
                        path[v] = new_path
                        heapq.heappush(heap, (new_dist, new_path, v))

    if dist[target] == INF:
        return (float("inf"), [])

    # Format distance
    distance = round(dist[target], 4) if not isinstance(dist[target], int) else int(dist[target])
    return (distance, path[target])
