```python
def line_segment_intersection(p1, p2, p3, p4):
    def is_valid_point(p):
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            return False
        try:
            x, y = float(p[0]), float(p[1])
        except (TypeError, ValueError):
            return False
        return True

    points = [p1, p2, p3, p4]
    for p in points:
        if not is_valid_point(p):
            raise ValueError("Invalid point")

    def eq(a, b):
        return abs(a - b) < 1e-9

    def sub(p, q):
        return (p[0] - q[0], p[1] - q[1])

    def dot(a, b):
        return a[0] * b[0] + a[1] * b[1]

    def cross(a, b):
        return a[0] * b[1] - a[1] * b[0]

    A, B, C, D = p1, p2, p3, p4
    if eq(A[0], B[0]) and eq(A[1], B[1]):
        raise ValueError("Degenerate segment")
    if eq(C[0], D[0]) and eq(C[1], D[1]):
        raise ValueError("Degenerate segment")

    Ax, Ay = A
    Bx, By = B
    Cx, Cy = C
    Dx, Dy = D

    dx1, dy1 = Bx - Ax, By - Ay
    dx2, dy2 = Dx - Cx, Dy - Cy

    det = dx1 * dy2 - dx2 * dy1

    if not eq(det, 0.0):
        det_inv = 1.0 / det
        dx3 = Cx - Ax
        dy3 = Cy - Ay
        t_numer = dx3 * dy2 - dx2 * dy3
        u_numer = dx1 * dy3 - dx3 * dy1
        t = t_numer * det_inv
        u = u_numer * det_inv
        if 0 <= t <= 1 and 0 <= u <= 1:
            x = Ax + t * dx1
            y = Ay + t * dy1
            x_round = round(x, 4) if not eq(x, int(x)) else int(x)
            y_round = round(y, 4) if not eq(y, int(y)) else int(y)
            return ("point", (x_round, y_round))
        else:
            return ("none", None)
    else:
        # Check collinearity by verifying if C lies on AB's line
        cross1 = cross(sub(B, A), sub(C, A))
        if not eq(cross1, 0.0):
            return ("none", None)

        # Collinear: check overlap
        def param(p, A, B):
            dx, dy = B[0] - A[0], B[1] - A[1]
            if eq(dx, 0.0) and eq(dy, 0.0):
                return 0.0
            if not eq(dx, 0.0):
                return (p[0] - A[0]) / dx
            else:
                return (p[1] - A[1]) / dy

        tA = param(A, A, B)
        tB = param(B, A, B)
        tC = param(C, A, B)
        tD = param(D, A, B)

        t_start = max(min(tC, tD), min(tA, tB))
        t_end = min(max(tC, tD), max(tA, tB))

        if t_start > t_end + 1e-9:
            return ("none", None)

        x1 = Ax + t_start * dx1
        y1 = Ay + t_start * dy1
        x2 = Ax + t_end * dx1
        y2 = Ay + t_end * dy1

        def round_point(p):
            x, y = p
            x = round(x, 4) if not eq(x, int(x)) else int(x)
            y = round(y, 4) if not eq(y, int(y)) else int(y)
