import itertools

def are_graphs_isomorphic(n_nodes, edges1, edges2):
    # Input validation
    if not isinstance(n_nodes, int) or isinstance(n_nodes, bool):
        raise ValueError("n_nodes must be an integer, not a boolean")
    if not (0 <= n_nodes <= 8):
        raise ValueError("n_nodes must be between 0 and 8 inclusive")
    if isinstance(edges1, bool) or isinstance(edges2, bool):
        raise ValueError("edges1 and edges2 must not be booleans")

    # Validate edges
    def validate_edges(edges, n):
        if not hasattr(edges, '__iter__') or isinstance(edges, str):
            raise ValueError("edges must be a sequence")
        for edge in edges:
            if not isinstance(edge, (list, tuple)) or len(edge) != 2:
                raise ValueError("each edge must be a 2-tuple or list")
            u, v = edge
            if not isinstance(u, int) or not isinstance(v, int):
                raise ValueError("edge elements must be integers")
            if not (0 <= u < n and 0 <= v < n):
                raise ValueError("edge nodes must be in range [0, n_nodes)")
            if u == v:
                continue  # self-loops are ignored
            if not (0 <= u < n and 0 <= v < n):
                raise ValueError("edge nodes must be in range [0, n_nodes)")

    validate_edges(edges1, n_nodes)
    validate_edges(edges2, n_nodes)

    # Process edges (remove self-loops)
    def process_edges(edges, n):
        edge_set = set()
        for u, v in edges:
            if u != v:
                edge_set.add(frozenset({u, v}))
        return edge_set

    graph1 = process_edges(edges1, n_nodes)
    graph2 = process_edges(edges2, n_nodes)

    # Pruning checks
    if len(graph1) != len(graph2):
        return False

    # Degree sequence check
    def get_degree_sequence(edge_set, n):
        degrees = [0] * n
        for edge in edge_set:
            u, v = edge
            degrees[u] += 1
            degrees[v] += 1
        return sorted(degrees)

    deg_seq1 = get_degree_sequence(graph1, n_nodes)
    deg_seq2 = get_degree_sequence(graph2, n_nodes)
    if deg_seq1 != deg_seq2:
        return False

    # Check permutations for isomorphism
    if n_nodes == 0:
        return True  # Both are empty graphs

    # Generate all possible permutations of nodes
    for perm in itertools.permutations(range(n_nodes)):
        # Map each node u in graph1 to perm[u], check if edges match
        is_isomorphic = True
        for edge in graph1:
            u, v = list(edge)
            pu = perm[u]
            pv = perm[v]
            if frozenset({pu, pv}) not in graph2:
                is_isomorphic = False
                break
        if is_isomorphic:
            return True

    return False
