import math
import random

def minimum_enclosing_circle(points):
    if not isinstance(points, (list, tuple)) or len(points) == 0:
        raise ValueError("Invalid points sequence")
    for i, p in enumerate(points):
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            raise ValueError(f"Point {i} is invalid")
        for coord in p:
            if isinstance(coord, bool):
                raise ValueError(f"Boolean coordinate in point {i}")
            if not isinstance(coord, (int, float)):
                raise ValueError(f"Non-numeric coordinate in point {i}")
    points = list(points)
    random.shuffle(points)

    def welzl(points, boundary):
        if not points and len(boundary) == 3:
            return _circumcircle(boundary)
        if not points or len(boundary) == 3:
            if len(boundary) == 2:
                return _circle_from_two(boundary)
            elif len(boundary) == 1:
                return (boundary[0], 0.0)
            else:
                raise ValueError("Unexpected boundary size")
        p = points[0]
        remaining = points[1:]
        circle = welzl(remaining, boundary)
        cx, cy = circle[0]
        r = circle[1]
        if (p[0] - cx)**2 + (p[1] - cy)**2 <= r**2 + 1e-7:
            return circle
        new_boundary = boundary + [p]
        return welzl(remaining, new_boundary)

    def _circle_from_two(p1, p2):
        cx = (p1[0] + p2[0]) / 2
        cy = (p1[1] + p2[1]) / 2
        r = math.hypot(p1[0] - p2[0], p1[1] - p2[1]) / 2
        return ((cx, cy), r)

    def _circumcircle(points):
        if len(points) != 3:
            raise ValueError("Expected three points")
        A, B, C = points
        d = 2 * (A[0]*(B[1]-C[1]) + B[0]*(C[1]-A[1]) + C[0]*(A[1]-B[1]))
        if abs(d) < 1e-9:
            return _circle_from_two(
                max(points, key=lambda p: min([math.hypot(p[0]-q[0], p[1]-q[1]) for q in points if q != p])),
                min(points, key=lambda p: max([math.hypot(p[0]-q[0], p[1]-q[1]) for q in points if q != p]))
            )
        x1, y1 = A
        x2, y2 = B
        x3, y3 = C
        cx = ((x1**2 + y1**2)*(B[1]-C[1]) + (x2**2 + y2**2)*(C[1]-A[1]) + (x3**2 + y3**2)*(A[1]-B[1])) / d
        cy = ((x1**2 + y1**2)*(C[0]-B[0]) + (x2**2 + y2**2)*(A[0]-C[0]) + (x3**2 + y3**2)*(B[0]-A[0])) / d
        r = math.hypot(x1 - cx, y1 - cy)
        return ((cx, cy), r)

    circle = welzl(points, [])
    cx, cy = circle[0]
    r = circle[1]

    def round_value(v):
        if abs(v - round(v)) < 1e-7:
            return round(v)
        return round(v, 4)

    cx_rounded = round_value(cx)
    cy_rounded = round_value(cy)
    r_rounded = round_value(r)

    return ((cx_rounded, cy_rounded), r_rounded)
