def find_articulation_points(n_nodes, edges):
    if not isinstance(n_nodes, int) or isinstance(n_nodes, bool):
        raise ValueError("n_nodes must be a non-negative integer")
    if n_nodes < 0:
        raise ValueError("n_nodes must be a non-negative integer")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")
    for i, (u, v) in enumerate(edges):
        if not isinstance(u, int) or isinstance(u, bool) or not isinstance(v, int) or isinstance(v, bool):
            raise ValueError(f"Edge {i} has invalid type")
        if not (0 <= u < n_nodes) or not (0 <= v < n_nodes):
            raise ValueError(f"Edge {i} has out-of-range vertex")
    adj = [[] for _ in range(n_nodes)]
    for u, v in edges:
        if u != v:
            adj[u].append(v)
            adj[v].append(u)
    visited = [False] * n_nodes
    disc = [float('inf')] * n_nodes
    low = [float('inf')] * n_nodes
    parent = [-1] * n_nodes
    ap = [False] * n_nodes
    time = 0

    def dfs(u):
        nonlocal time
        children = 0
        visited[u] = True
        disc[u] = time
        low[u] = time
        time += 1
        for v in adj[u]:
            if parent[u] == v:
                continue
            if not visited[v]:
                parent[v] = u
                children += 1
                dfs(v)
                low[u] = min(low[u], low[v])
                if parent[u] == -1:  # root
                    if children >= 2:
                        ap[u] = True
                else:
                    if low[v] >= disc[u]:
                        ap[u] = True
            else:
                if disc[v] < low[u]:
                    low[u] = disc[v]

    for u in range(n_nodes):
        if not visited[u]:
            dfs(u)
    result = [i for i, is_ap in enumerate(ap) if is_ap]
    return sorted(result)
