def find_eulerian_trail_directed(n_nodes, edges):
    if not isinstance(n_nodes, int) or n_nodes < 0:
        raise ValueError("Invalid n_nodes")
    if not edges:
        if n_nodes == 0:
            return []
        elif n_nodes == 1:
            return [0]
        else:
            return None
    adj = {u: [] for u in range(n_nodes)}
    for u, v in edges:
        if not (0 <= u < n_nodes and 0 <= v < n_nodes):
            raise ValueError("Invalid edge")
        adj[u].append(v)
    # Sort adjacency lists in descending order for deterministic popping
    for u in adj:
        adj[u].sort(reverse=True)
    # Compute delta for each node
    delta = [0] * n_nodes
    for u in adj:
        delta[u] = len(adj[u])
    for u, v in edges:
        delta[u] -= 1  # in-degree
    # Check degree conditions
    start_nodes = []
    end_nodes = []
    for d in delta:
        if d == 1:
            start_nodes.append(d)
        elif d == -1:
            end_nodes.append(d)
        elif d != 0:
            return None
    if len(start_nodes) != 1 or len(end_nodes) != 1:
        if not all(d == 0 for d in delta):
            return None
    # Determine start node
    start = 0
    if any(d == 1 for d in delta):
        for u in range(n_nodes):
            if delta[u] == 1:
                start = u
                break
    else:
        # Eulerian circuit, choose the smallest node with outgoing edges
        for u in range(n_nodes):
            if adj[u]:
                start = u
                break
    # Hierholzer's algorithm
    stack = [start]
    circuit = []
    current = start
    while stack:
        if adj[current]:
            stack.append(current)
            next_node = adj[current].pop()
            current = next_node
        else:
            circuit.append(current)
            current = stack.pop() if stack else None
    # Check if all edges are used (adj lists are empty)
    for u in adj:
        if adj[u]:
            return None
    # Check trail length
    if len(circuit) != len(edges) + 1:
        return None
    return circuit
