RATIONALE: The approach validates the input tree structure, ensuring it meets the criteria of being connected and acyclic. It uses BFS to find the two farthest nodes (u and v), which defines the diameter. The radius is computed as the ceiling of half the diameter. The centers are determined based on the midpoint(s) of the u-v path. BFS is chosen for its efficiency in tree traversal and distance calculation.

```python
import collections

def tree_diameter_and_radius(n_nodes, edges):
    if not isinstance(n_nodes, int) or n_nodes <= 0:
        raise ValueError("Invalid n_nodes")
    if len(edges) != n_nodes - 1:
        raise ValueError("Invalid number of edges")
    for u, v in edges:
        if not (isinstance(u, int) and isinstance(v, int)):
            raise ValueError("Edge elements must be integers")
        if not (0 <= u < n_nodes and 0 <= v < n_nodes):
            raise ValueError("Vertex index out of range")

    # Build adjacency list
    adj = [[] for _ in range(n_nodes)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if connected
    def bfs_check(start):
        visited = [False] * n_nodes
        queue = collections.deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited)

    if not bfs_check(0):
        raise ValueError("Graph is disconnected")

    # BFS to find farthest node and predecessors
    def bfs_farthest(start):
        visited = [False] * n_nodes
        distance = [0] * n_nodes
        predecessors = [-1] * n_nodes
        max_dist = 0
        farthest_node = start
        queue = collections.deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[node] + 1
                    predecessors[neighbor] = node
                    queue.append(neighbor)
                    if distance[neighbor] > max_dist:
                        max_dist = distance[neighbor]
                        farthest_node = neighbor
        return farthest_node, predecessors, max_dist

    # First BFS from arbitrary node (0)
    u, _, _ = bfs_farthest(0)
    # Second BFS from u to find v and predecessors
    v, predecessors, diameter = bfs_farthest(u)

    if n_nodes == 1:
        return (0, 0, (0,))

    # Reconstruct path from u to v
    path = []
    current = v
    while current != -1:
        path.append(current)
        current = predecessors[current]
    path.reverse()

    D = diameter
    R = (D + 1) // 2
    if D % 2 == 0:
        center_idx = D // 2
        centers = [path[center_idx]]
    else:
        center_idx1 = D // 2
        center_idx2 = D // 2 + 1
        centers = [path[center_idx1], path[center_idx2]]

    centers = tuple(sorted(set(centers)))
    return (D, R, centers)
