To simulate the SCAN (LOOK) algorithm for an elevator, we initialize the elevator's state and process calls by moving in the current direction until no more calls remain in that direction, at which point the elevator reverses. Input validation ensures correctness and robustness.

```python
def simulate_elevator_scan(n_floors, start_floor, initial_direction, stop_time, calls):
    if type(n_floors) is not int or n_floors < 2:
        raise ValueError
    if type(start_floor) is not int or not (0 <= start_floor < n_floors):
        raise ValueError
    if initial_direction not in ("up", "down"):
        raise ValueError
    if type(stop_time) is not int or stop_time < 0:
        raise ValueError
    if not isinstance(calls, (list, tuple)):
        raise ValueError
    if len(set(calls)) != len(calls):
        raise ValueError
    for f in calls:
        if type(f) is not int or not (0 <= f < n_floors):
            raise ValueError

    current_floor = start_floor
    direction = initial_direction
    clock = 0
    visited = []
    pending = set(calls)

    if start_floor in pending:
        visited.append(start_floor)
        pending.remove(start_floor)
        clock += stop_time

    while pending:
        has_ahead = False
        if direction == "up":
            has_ahead = any(f > current_floor for f in pending)
        else:
            has_ahead = any(f < current_floor for f in pending)
        if not has_ahead:
            direction = "down" if direction == "up" else "up"
        current_floor += 1 if direction == "up" else -1
        clock += 1
        if current_floor in pending:
            visited.append(current_floor)
            pending.remove(current_floor)
            clock += stop_time

    return (clock, visited)
