```python
def knapsack_01_reconstruct(capacity, items):
    # Input validation
    if not isinstance(capacity, int) or capacity < 0:
        raise ValueError("Invalid capacity")
    if not items:
        return (0, [])
    item_ids = set()
    for i, (w, v, iid) in enumerate(items):
        if not isinstance(w, int) or w <= 0:
            raise ValueError(f"Invalid weight at index {i}")
        if not isinstance(v, int) or v < 0:
            raise ValueError(f"Invalid value at index {i}")
        if type(iid) is bool:
            raise ValueError(f"Invalid item_id at index {i}")
        if iid in item_ids:
            raise ValueError(f"Duplicate item_id at index {i}")
        item_ids.add(iid)

    # DP initialization
    n = len(items)
    dp = [0] * (capacity + 1)  # dp[w] = max value for capacity w
    # Track for each (value, weight) the set of item IDs

    # First pass: compute max value
    for i in range(n):
        w_i, v_i, id_i = items[i]
        for w in range(capacity, w_i - 1, -1):
            if dp[w - w_i] + v_i > dp[w]:
                dp[w] = dp[w - w_i] + v_i

    max_value = max(dp)
    # Find the best capacity w with max value and minimal weight
    best_w = -1
    best_weight = capacity + 1
    for w in range(capacity, -1, -1):  # Prefer smaller capacities if tied
        if dp[w] == max_value:
            if w < best_weight:
                best_weight = w
                best_w = w

    # Reconstruct the chosen items
    chosen = []
    w = best_w
    for i in reversed(range(n)):
        weight, value, item_id = items[i]
        if w >= weight and dp[w] == dp[w - weight] + value:
            chosen.append(item_id)
            w -= weight

    chosen.sort(key=lambda x: str(x))
    return (max_value, chosen)
