def longest_common_subsequence_three(s1, s2, s3):
    # Input validation
    for s in [s1, s2, s3]:
        if not isinstance(s, str) or isinstance(s, bool):
            raise ValueError("All inputs must be strings.")
        if len(s) > 25:
            raise ValueError("String length exceeds 25 characters.")
    if not s1 or not s2 or not s3:
        return ""

    n1, n2, n3 = len(s1), len(s2), len(s3)

    # Initialize 3D DP table
    dp = [[[0]*(n3+1) for _ in range(n2+1)] for _ in range(n1+1)]

    # Fill DP table
    for i in range(1, n1+1):
        for j in range(1, n2+1):
            for k in range(1, n3+1):
                if s1[i-1] == s2[j-1] == s3[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(
                        dp[i-1][j][k],
                        dp[i][j-1][k],
                        dp[i][j][k-1]
                    )

    # Backtrack to find the actual LCS with lex tie-break
    def backtrack(i, j, k):
        if i == 0 or j == 0 or k == 0:
            return ""
        # Check if current characters match
        if s1[i-1] == s2[j-1] == s3[k-1]:
            return backtrack(i-1, j-1, k-1) + s1[i-1]
        # Else, try all possible directions that could lead to the current dp value
        candidates = []
        # Check all three directions
        for (di, dj, dk) in [(-1,0,0), (0,-1,0), (0,0,-1)]:
            ni, nj, nk = i + di, j + dj, k + dk
            if dp[ni][nj][nk] == dp[i][j][k]:
                candidates.append(backtrack(ni, nj, nk))
        # Among candidates with max length, choose lex smallest
        max_len = max(len(c) for c in candidates)
        valid = [c for c in candidates if len(c) == max_len]
        return min(valid)

    return backtrack(n1, n2, n3)
