def simulate_clock_cache(capacity, page_requests):
    if not isinstance(capacity, int) or isinstance(capacity, bool):
        raise ValueError("Invalid capacity")
    if capacity < 1:
        raise ValueError("Capacity must be at least 1")
    if not hasattr(page_requests, '__iter__'):
        raise ValueError("Invalid page_requests")

    for p in page_requests:
        if isinstance(p, bool):
            raise ValueError("Page identifier cannot be a boolean")
        if not (isinstance(p, (str, int)) and 
                (not isinstance(p, str) or len(p) > 0)):
            raise ValueError("Invalid page identifier")

    if not page_requests:
        return (0, 0, [])

    frames = []
    hand = 0
    page_faults = 0
    page_hits = 0

    for page in page_requests:
        # Check for hit
        hit = False
        for i in range(len(frames)):
            if frames[i][0] == page:
                frames[i] = (page, 1)
                hit = True
                page_hits += 1
                break
        if hit:
            continue

        # Miss handling
        page_faults += 1
        if len(frames) < capacity:
            # Add new frame
            frames.append([page, 0])
        else:
            # Find victim using clock algorithm
            while True:
                if frames[hand][1] == 1:
                    # Clear reference bit
                    frames[hand] = (frames[hand][0], 0)
                    hand = (hand + 1) % capacity
                else:
                    # Replace this frame
                    frames[hand] = (page, 0)
                    hand = (hand + 1) % capacity
                    break

    # Extract frame contents
    frame_contents = [f[0] for f in frames]
    return (page_faults, page_hits, frame_contents)
