def simulate_turing_machine(tape, transitions, start_state, accept_states, max_steps):
    # Validate inputs
    if not isinstance(tape, str):
        raise ValueError("Tape must be a string.")
    if not isinstance(transitions, dict):
        raise ValueError("Transitions must be a dictionary.")
    for (state, sym), (nstate, wsym, dir) in transitions.items():
        if isinstance(state, bool) or isinstance(sym, bool):
            raise ValueError("States and symbols cannot be bool.")
        if not isinstance(sym, str) or len(sym) != 1:
            raise ValueError("Symbols must be single characters.")
        if not isinstance(nstate, (int, str)) or isinstance(nstate, bool):
            raise ValueError("Next state must be int or string, not bool.")
        if not isinstance(wsym, str) or len(wsym) != 1:
            raise ValueError("Write symbol must be single character.")
        if dir not in ('L', 'R'):
            raise ValueError("Invalid direction.")
    if isinstance(start_state, bool):
        raise ValueError("Start state cannot be bool.")
    if not (isinstance(accept_states, (list, tuple, set)) and all(not isinstance(s, bool) for s in accept_states)):
        raise ValueError("Accept states must be a sequence of non-bool states.")
    if not isinstance(max_steps, int) or max_steps < 1:
        raise ValueError("Max steps must be a positive integer.")

    # Initialize tape as a dictionary
    tape_dict = {i: c for i, c in enumerate(tape)}
    head = 0
    current_state = start_state
    steps = 0

    while True:
        # Check acceptance
        if current_state in accept_states:
            return ("accepted", steps, _get_final_tape(tape_dict))
        # Check step limit
        if steps == max_steps:
            return ("step_limit", steps, _get_final_tape(tape_dict))
        # Read symbol
        read_sym = tape_dict.get(head, ' ')
        # Check transition
        if (current_state, read_sym) not in transitions:
            return ("halted", steps, _get_final_tape(tape_dict))
        # Apply transition
        next_state, write_sym, direction = transitions[(current_state, read_sym)]
        tape_dict[head] = write_sym
        head = head - 1 if direction == 'L' else head + 1
        current_state = next_state
        steps += 1

def _get_final_tape(tape_dict):
    non_blank = [k for k, v in tape_dict.items() if v != ' ']
    if not non_blank:
        return ""
    min_idx = min(non_blank)
    max_idx = max(non_blank)
    result = []
    for i in range(min_idx, max_idx + 1):
        result.append(tape_dict.get(i, ' '))
    return ''.join(result)
