```python
def min_edit_operations(source, target, costs):
    # Input validation
    if not isinstance(source, str) or not isinstance(target, str):
        raise ValueError("source and target must be strings")
    if len(source) > 30 or len(target) > 30:
        raise ValueError("string length exceeds 30")
    if isinstance(costs, tuple):
        if len(costs) != 3:
            raise ValueError("costs tuple must have 3 elements")
        insert_cost, delete_cost, replace_cost = costs
        for c in [insert_cost, delete_cost, replace_cost]:
            if not isinstance(c, int) or c <= 0:
                raise ValueError("costs must be positive integers")
    elif isinstance(costs, dict):
        if "insert" not in costs or "delete" not in costs or "replace" not in costs:
            raise ValueError("costs dict must have 'insert', 'delete', 'replace' keys")
        insert_cost = costs["insert"]
        delete_cost = costs["delete"]
        replace_cost = costs["replace"]
        for c in [insert_cost, delete_cost, replace_cost]:
            if not isinstance(c, int) or c <= 0:
                raise ValueError("costs must be positive integers")
    else:
        raise ValueError("costs must be a tuple or dict")

    # Initialize DP table and operation tracking
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    ops = [[None] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(1, m + 1):
        dp[i][0] = i * delete_cost
        ops[i][0] = ("delete", source[i-1])
    for j in range(1, n + 1):
        dp[0][j] = j * insert_cost
        ops[0][j] = ("insert", target[j-1])

    # Fill DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i-1] == target[j-1]:
                dp[i][j] = dp[i-1][j-1]
                ops[i][j] = ("keep", source[i-1])
            else:
                candidates = []
                # Replace
                candidates.append((dp[i-1][j-1] + replace_cost, "replace"))
                # Delete
                candidates.append((dp[i-1][j] + delete_cost, "delete"))
                # Insert
                candidates.append((dp[i][j-1] + insert_cost, "insert"))

                best_cost = None
                best_op = None
                for cost, op in candidates:
                    if best_cost is None or cost < best_cost:
                        best_cost = cost
                        best_op = op
                    elif cost == best_cost:
                        # Tie-breaker: replace > delete > insert
                        if op == "replace" and best_op not in ["replace"]:
                            best_op = op
                        elif op == "delete" and best_op == "insert":
                            best_op = op
                dp[i][j] = best_cost
                if best_op == "replace":
                    ops[i][j] = ("replace", source[i-1], target[j-1])
                elif best_op == "delete":
                    ops[i][j] = ("delete", source[i-1])
                else:  # insert
                    ops[i][j] = ("insert", target[j-1])

    # Backtrack to get operations in forward order
    i, j = m, n
    operations = []
    while i > 0 or j > 0:
        if i > 0 and j > 0 and ops[i][j][0] == "keep":
            operations.append(ops[i][j])
            i -= 1
            j -= 1
        elif i > 0 and j > 0 and ops[i][j][0] == "replace":
            operations.append(ops[i][j])
            i -= 1
            j -= 1
        elif i > 0 and ops[i][j][0] == "delete":
            operations.append(ops[i][j])
            i -= 1
        else:  # insert
            operations.append(ops[i][j])
            j -= 1

    # Reverse operations to get forward order
    operations.reverse()
    return dp[m][n], operations
