def max_submatrix_sum(matrix):
    # Validate input
    if not matrix or not matrix[0]:
        raise ValueError("Empty matrix")
    R = len(matrix)
    C = len(matrix[0])
    for i, row in enumerate(matrix):
        if len(row) != C:
            raise ValueError("Ragged rows")
        for j, x in enumerate(row):
            if not isinstance(x, int) or type(x) is bool:
                raise ValueError("Non-integer element")

    best_sum = None
    best_r1, best_c1, best_r2, best_c2 = 0, 0, 0, 0

    for r1 in range(R):
        temp = [0] * C
        for r2 in range(r1, R):
            for c in range(C):
                temp[c] = matrix[r2][c] + (temp[c] if r2 > r1 else 0)

            # Apply 1D Kadane's algorithm
            current_sum = 0
            current_c1 = 0
            kadane_sum = None
            kadane_c1, kadane_c2 = 0, 0
            for c in range(C):
                current_sum += temp[c]
                if kadane_sum is None or current_sum > kadane_sum:
                    kadane_sum = current_sum
                    kadane_c1 = current_c1
                    kadane_c2 = c
                elif current_sum < 0:
                    current_sum = 0
                    current_c1 = c + 1
            # Handle all-negative case
            if kadane_sum is None:
                kadane_sum = max(temp)
                kadane_c1 = temp.index(kadane_sum)
                kadane_c2 = kadane_c1

            # Compare with best
            current_candidate_sum = kadane_sum
            current_r1, current_r2 = r1, r2
            current_c1_k = kadane_c1
            current_c2_k = kadane_c2

            area_current = (current_r2 - current_r1 + 1) * (current_c2_k - current_c1_k + 1)
            if best_sum is None:
                best_sum = current_candidate_sum
                best_r1, best_c1, best_r2, best_c2 = current_r1, current_c1_k, current_r2, current_c2_k
            else:
                if current_candidate_sum > best_sum:
                    best_sum = current_candidate_sum
                    best_r1, best_c1, best_r2, best_c2 = current_r1, current_c1_k, current_r2, current_c2_k
                elif current_candidate_sum == best_sum:
                    area_current = (current_r2 - current_r1 + 1) * (current_c2_k - current_c1_k + 1)
                    area_best = (best_r2 - best_r1 + 1) * (best_c2 - best_c1 + 1)
                    if area_current < area_best:
                        best_r1, best_c1, best_r2, best_c2 = current_r1, current_c1_k, current_r2, current_c2_k
                    elif area_current == area_best:
                        current_tuple = (current_r1, current_c1_k, current_r2, current_c2_k)
                        best_tuple = (best_r1, best_c1, best_r2, best_c2)
                        if current_tuple < best_tuple:
                            best_r1, best_c1, best_r2, best_c2 = current_r1, current_c1_k, current_r2, current_c2_k
    return (best_sum, (best_r1, best_c1, best_r2, best_c2))
