def longest_alternating_subseq(nums):
    # Input validation
    if not isinstance(nums, (list, tuple)):
        raise ValueError
    if len(nums) > 50:
        raise ValueError
    for num in nums:
        if not isinstance(num, int):
            raise ValueError

    n = len(nums)
    if n == 0:
        return (0, ())

    # Initialize DP arrays
    up = [(1, [nums[i]]) for i in range(n)]
    down = [(1, [nums[i]]) for i in range(n)]

    for i in range(n):
        for j in range(i):
            if nums[i] > nums[j]:
                # Can extend a down[j] to up[i]
                new_length = down[j][0] + 1
                new_seq = down[j][1] + [nums[i]]
                if new_length > up[i][0] or (new_length == up[i][0] and new_seq < up[i][1]):
                    up[i] = (new_length, new_seq)
            elif nums[i] < nums[j]:
                # Can extend a up[j] to down[i]
                new_length = up[j][0] + 1
                new_seq = up[j][1] + [nums[i]]
                if new_length > down[i][0] or (new_length == down[i][0] and new_seq < down[i][1]):
                    down[i] = (new_length, new_seq)

        # Also check if nums[i] == nums[j], do nothing

    # Find the maximum length and corresponding sequence
    max_len = 1
    best_seq = [nums[0]]
    for i in range(n):
        for arr in [up[i], down[i]]:
            if arr[0] > max_len or (arr[0] == max_len and arr[1] < best_seq):
                max_len = arr[0]
                best_seq = arr[1]

    return (max_len, tuple(best_seq))
