def subset_sum_ways(nums, target):
    MOD = 10**9 + 7
    # Validate inputs
    if not isinstance(nums, (list, tuple)):
        raise ValueError
    if not all(isinstance(x, int) and x > 0 for x in nums):
        raise ValueError
    if not isinstance(target, int) or target < 0:
        raise ValueError
    if target == 0:
        return (1, 0)

    n = len(nums)
    # dp[k] is a dictionary {sum: count} for subsets of size k
    dp = [{} for _ in range(n + 1)]
    dp[0][0] = 1

    for num in nums:
        for k in range(n, -1, -1):
            for s in list(dp[k].keys()):
                current = dp[k][s]
                new_sum = s + num
                new_k = k + 1
                if new_sum > target:
                    continue
                if new_sum in dp[new_k]:
                    dp[new_k][new_sum] = (dp[new_k][new_sum] + current) % MOD
                else:
                    dp[new_k][new_sum] = current

    total = 0
    min_size = None
    for k in range(n + 1):
        cnt = dp[k].get(target, 0)
        if cnt > 0:
            total = (total + cnt) % MOD
            if min_size is None or k < min_size:
                min_size = k
    if total == 0:
        return (0, None)
    return (total, min_size)
