def simulate_leaky_bucket(capacity, leak_rate, packets):
    # Input validation
    if not (isinstance(capacity, int) and capacity >= 1):
        raise ValueError("capacity must be a positive integer >= 1")
    if not (isinstance(leak_rate, int) and leak_rate >= 1):
        raise ValueError("leak_rate must be a positive integer >= 1")

    packet_ids = set()
    prev_arrival = -1
    for i, (arr, size, pid) in enumerate(packets):
        if not (isinstance(arr, int) and arr >= 0):
            raise ValueError(f"packet {i} has invalid arrival_time")
        if not (isinstance(size, int) and size >= 1):
            raise ValueError(f"packet {i} has invalid size_bytes")
        if not (isinstance(pid, (str, int)) and len(str(pid)) > 0):
            raise ValueError(f"packet {i} has invalid packet_id")
        if pid in packet_ids:
            raise ValueError(f"duplicate packet_id: {pid}")
        packet_ids.add(pid)
        if arr < prev_arrival:
            raise ValueError("arrival times must be non-decreasing")
        prev_arrival = arr

    accepted_count = 0
    dropped_count = 0
    departures = {}
    d_prev = 0.0  # Previous departure time

    for arr, size, pid in packets:
        start = max(arr, d_prev)
        if d_prev >= arr:  # Buffer was still draining when packet arrives
            buffered = (d_prev - arr) * leak_rate
        else:  # Buffer was empty when packet arrives
            buffered = 0.0

        if buffered + size > capacity:
            dropped_count += 1
        else:
            accepted_count += 1
            dep = start + (size / leak_rate)
            departures[pid] = round(dep, 4) if dep % 1 else int(dep)
            d_prev = dep

    return (accepted_count, dropped_count, departures)
