def format_netstring(data):
    if isinstance(data, str):
        payload = data.encode('utf-8')
    elif isinstance(data, bytes):
        payload = data
    else:
        raise ValueError("Data must be bytes or str")
    length = len(payload)
    length_str = str(length)
    if length != 0 and length_str[0] == '0':
        raise ValueError("Length cannot have leading zeros")
    netstring = f"{length_str}:{payload},".encode('ascii')
    return netstring

def parse_netstring(blob):
    if not isinstance(blob, (bytes, bytearray)):
        raise ValueError("Blob must be bytes or bytearray")
    colon_index = blob.find(b':')
    if colon_index == -1:
        raise ValueError("Missing colon")
    length_str = blob[:colon_index]
    rest = blob[colon_index+1:]
    if not length_str.isdigit():
        raise ValueError("Invalid length characters")
    if len(length_str) > 1 and length_str[0] == '0':
        raise ValueError("Leading zeros in length")
    try:
        n = int(length_str)
    except ValueError:
        raise ValueError("Invalid length")
    if len(rest) < n + 1:
        raise ValueError("Insufficient bytes for payload and comma")
    payload = rest[:n]
    if rest[n] != ord(','):
        raise ValueError("Missing or incorrect trailing comma")
    remainder = rest[n+1:]
    return (payload, remainder)
