def calculate_isbn13_check(digits12):
    if isinstance(digits12, str):
        if len(digits12) != 12 or not digits12.isdigit():
            raise ValueError
        digits = [int(c) for c in digits12]
    elif isinstance(digits12, (list, tuple)):
        if len(digits12) != 12:
            raise ValueError
        digits = []
        for d in digits12:
            if not (isinstance(d, int) and not isinstance(d, bool)) or not (0 <= d <= 9):
                raise ValueError
            digits.append(d)
    else:
        raise ValueError
    total = 0
    for i in range(12):
        if i % 2 == 0:
            total += digits[i] * 1
        else:
            total += digits[i] * 3
    r = total % 10
    check_digit = (10 - r) % 10
    return check_digit

