            raise ValueError
    cleaned = code.replace('-', '').replace(' ', '')
    if len(cleaned) != 13 or not cleaned.isdigit():
        return False
    if not (cleaned.startswith('978') or cleaned.startswith('979')):
        return False
    first12 = cleaned[:12]
    computed = calculate_isbn13_check(first12)
    actual = int(cleaned[12])
    return computed == actual
