def parse_http_range(header, total_size):
    if not isinstance(total_size, int) or total_size <= 0:
        raise ValueError("total_size must be a positive integer")
    if not header.startswith("bytes="):
        raise ValueError("Header must start with 'bytes='")

    range_spec = header[len("bytes="):].strip()
    if not range_spec:
        raise ValueError("Invalid range specification")

    specs = [s.strip() for s in range_spec.split(',')]
    ranges = []

    for spec in specs:
        if not spec:
            raise ValueError("Empty range specification")
        parts = spec.split('-')
        if len(parts) != 2:
            raise ValueError(f"Invalid range format: {spec}")
        start_part, end_part = parts

        if start_part == '' and end_part == '':
            raise ValueError("Empty range specification")

        if start_part == '':
            # Handle '-suffix' case
            if not end_part.isdigit() or int(end_part) <= 0:
                raise ValueError(f"Invalid suffix: {end_part}")
            suffix = int(end_part)
            start = max(0, total_size - suffix)
            end = total_size - 1
        elif end_part == '':
            # Handle 'start-' case
            if not start_part.isdigit() or int(start_part) < 0:
                raise ValueError(f"Invalid start: {start_part}")
            start = int(start_part)
            if start >= total_size:
                raise ValueError("Start exceeds total size")
            end = total_size - 1
        else:
            # Handle 'start-end' case
            if not start_part.isdigit() or not end_part.isdigit():
                raise ValueError(f"Invalid range numbers: {spec}")
            start = int(start_part)
            end = int(end_part)
            if start < 0 or end < 0:
                raise ValueError("Negative byte positions")
            if start > end:
                raise ValueError("Start exceeds end")
            if start >= total_size:
                raise ValueError("Start exceeds total size")
            if end >= total_size:
