parse_card and format_card functions handle standard playing cards. parse_card converts a string to a tuple, validating length, rank, and suit. format_card converts rank and suit to a canonical string, ensuring correct ranges and types. Both functions validate inputs strictly, raising ValueError for invalid cases.

```python
def parse_card(card_str):
    if len(card_str) not in (2, 3):
        raise ValueError
    suit = card_str[-1].lower()
    if suit not in {'c', 'd', 'h', 's'}:
        raise ValueError
    if len(card_str) == 3:
        rank_str = card_str[:2].lower()
    else:
        rank_str = card_str[0].lower()
    if rank_str == '10':
        rank = 10
    else:
        if len(rank_str) != 1:
            raise ValueError
        if rank_str in {'j', 'q', 'k', 'a'}:
            rank = {'j': 11, 'q': 12, 'k': 13, 'a': 14}[rank_str]
        elif rank_str.isdigit():
            num = int(rank_str)
            if 2 <= num <= 9:
                rank = num
            else:
                raise ValueError
        else:
            raise ValueError
    return (rank, suit)

def format_card(rank, suit):
    if not isinstance(rank, int) or isinstance(rank, bool):
        raise ValueError
    if rank < 2 or rank > 14:
        raise ValueError
    suit = suit.lower()
    if len(suit) != 1 or suit not in {'c', 'd', 'h', 's'}:
        raise ValueError
    if rank == 14:
        rank_char = 'A'
    elif rank == 13:
        rank_char = 'K'
    elif rank == 12:
        rank_char = 'Q'
    elif rank == 11:
        rank_char = 'J'
    elif 2 <= rank <= 10:
        rank_char = str(rank)
    else:
        raise ValueError
    return f"{rank_char}{suit}"
