To implement the Möbius function, we factorize each number to check for squared primes and count distinct prime factors. For the Mertens function, we sum the Möbius function values up to n. Using a sieve approach optimizes the Möbius function computation for multiple values efficiently.

```python
def mobius_mu(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an integer >= 1")
    if n == 1:
        return 1
    factors = {}
    # Factorize n
    temp = n
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        factors[temp] = 1
    # Check for squared prime factors
    for exp in factors.values():
        if exp > 1:
            return 0
    k = len(factors)
    return (-1) ** k

def mertens_m(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an integer >= 1")
    if n == 0:
        raise ValueError("n must be >= 1")
    # Compute Mertens function using sieve for Möbius function
    mu = [1] * (n + 1)
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            for multiple in range(p, n + 1, p):
                is_prime[multiple] = False if multiple != p else is_prime[multiple]
                mu[multiple] *= -1
            p_square = p * p
            for multiple in range(p_square, n + 1, p_square):
                mu[multiple] = 0
    return sum(mu[1:n+1])

