To implement the Legendre and Jacobi symbols, we first validate the inputs. For the Legendre symbol, we ensure `p` is an odd prime, and compute using Euler's criterion. For the Jacobi symbol, we handle factors of 2 and apply quadratic reciprocity iteratively without factoring `n`.

```python
def legendre_symbol(a, p):
    if not isinstance(a, int) or not isinstance(p, int):
        raise TypeError("a and p must be integers")
    if p < 3 or p % 2 == 0:
        raise ValueError("p must be an odd prime >= 3")
    # Check if p is prime
    if p == 2:
        pass  # p is 2, but we've already checked p >=3
    else:
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
        if not is_prime:
            raise ValueError("p must be prime")
    a = a % p
    if a == 0:
        return 0
    ls = pow(a, (p - 1) // 2, p)
    if ls == p - 1:
        return -1
    return 1

def jacobi_symbol(a, n):
    if not isinstance(a, int) or not isinstance(n, int):
        raise TypeError("a and n must be integers")
    if n < 1 or n % 2 == 0:
        raise ValueError("n must be a positive odd integer")
    if n == 1:
        return 1
    a = a % n
    if a == 0:
        return 0
    res = 1
    while a != 0:
        if a % 2 == 0:
            t = 0
            while a % 2 == 0:
                a //= 2
                t += 1
            s = 1
            if n % 8 in (3, 5):
                s = -1
            res *= s ** t
        if a % 4 == 3 and n % 4 == 3:
            res *= -1
        a, n = n, a % n
    if n == 1:
        return res
    else:
        return 0

