To compute the Carmichael function λ(n), we factorize n into its prime components, compute λ for each prime power, and then find the least common multiple (LCM) of these values. Special cases for powers of 2 are handled separately.

```python
def carmichael_lambda(n):
    from math import gcd

    # Validation
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 1:
        raise ValueError

    if n == 1:
        return 1

    def factorize(x):
        factors = []
        count = 0
        while x % 2 == 0:
            count += 1
            x //= 2
        if count > 0:
            factors.append((2, count))
        i = 3
        while i * i <= x:
            count = 0
            while x % i == 0:
                count += 1
                x //= i
            if count > 0:
                factors.append((i, count))
            i += 2
        if x > 1:
            factors.append((x, 1))
        return factors

    factors = factorize(n)
    lambdas = []
    for (p, k) in factors:
        if p == 2:
            if k == 1:
                m = 1
            elif k == 2:
                m = 2
            else:
                m = 2 ** (k - 2)
        else:
            m = (p ** (k - 1)) * (p - 1)
        lambdas.append(m)

    def lcm_list(lst):
        current_lcm = 1
        for num in lst:
            current_gcd = gcd(current_lcm, num)
            current_lcm = (current_lcm * num) // current_gcd
        return current_lcm

    return lcm_list(lambdas)
```

