The functions `to_continued_fraction` and `from_continued_fraction` are implemented to handle the conversion between rational numbers and their simple continued fraction representations. The `to_continued_fraction` function uses the Euclidean algorithm to compute the coefficients, ensuring correct handling of negative values. The `from_continued_fraction` function reconstructs the fraction by processing the coefficients in reverse order, starting from the last term and building up the numerator and denominator step by step.

```python
def to_continued_fraction(num, den):
    if not isinstance(num, int) or not isinstance(den, int) or den <= 0:
        raise ValueError
    if isinstance(num, bool) or isinstance(den, bool):
        raise ValueError
    if den == 0:
        raise ValueError

    # Handle negative denominator by flipping signs
    if den < 0:
        num = -num
        den = -den

    coefficients = []
    while den != 0:
        a = num // den
        coefficients.append(a)
        remainder = num % den
        num, den = den, remainder
        # To handle negative remainders correctly
        if remainder < 0:
            num = -num
            den = -den
    return coefficients

def from_continued_fraction(terms):
    if not isinstance(terms, (list, tuple)) or len(terms) == 0:
        raise ValueError
    for i, term in enumerate(terms):
        if not isinstance(term, int):
            raise ValueError
        if i > 0 and term < 1:
            raise ValueError
    if len(terms) == 1:
        return (terms[0], 1)

    num, den = terms[-1], 1
    for term in reversed(terms[:-1]):
        next_num = term * num + den
        next_den = num
        num, den = next_num, next_den
    # Simplify the fraction
    from math import gcd
    common = gcd(num, den)
    num //= common
    den //= common
    return (num, den)

