    # Check if p is 3 mod 4, use shortcut
    if p % 4 == 3:
        x = pow(a, (p + 1) // 4, p)
        return min(x, p - x)
    # Tonelli-Shanks algorithm
    # Find Q and S such that p-1 = Q * 2^S
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1
    # Find a quadratic non-residue z
    z = 2
    while True:
        if pow(z, (p - 1) // 2, p) == p - 1:
