        i, temp = 0, t
        while temp != 1 and i < M:
            temp = pow(temp, 2, p)
            i += 1
        if i == M:
            return None  # No solution found, though Euler's criterion should have handled this
        b = pow(c, 1 << (M - i - 1), p)
        R = (R * b) % p
        t = (t * b * b) % p
        c = (b * b) % p
        M = i
