import math

def farey_sequence(n):
    if not isinstance(n, int) or type(n) is not int or n < 1:
        raise ValueError("n must be an integer >= 1")

    fractions = []
    for den in range(1, n + 1):
        for num in range(0, den + 1):
            if math.gcd(num, den) == 1:
                fractions.append((num, den))

    # Sort the fractions based on their value
    fractions.sort(key=lambda x: x[0] / x[1])

    # Remove duplicates, if any
    unique = []
    seen = set()
    for frac in fractions:
        if frac not in seen:
            seen.add(frac)
            unique.append(frac)

    # Ensure the sequence starts with (0,1) and ends with (1,1)
    if unique[0] != (0, 1):
        unique.insert(0, (0, 1))
    if unique[-1] != (1, 1):
        unique.append((1, 1))

    return unique

def farey_count(n):
    if not isinstance(n, int) or type(n) is not int or n < 1:
        raise ValueError("n must be an integer >= 1")

    def euler_totient(m):
        if m == 0:
            return 0
        totient = m
        i = 2
        while i * i <= m:
            if m % i == 0:
                while m % i == 0:
                    m //= i
                totient -= totient // i
            i += 1
        if m > 1:
            totient -= totient // m
        return totient

    total = 1  # Starting count with 0/1 and 1/1
    for m in range(1, n + 1):
        total += euler_totient(m)
    return total

