The function `max_clique` uses a brute-force approach to generate all possible subsets of nodes, checking each for being a clique. It ensures input validity, constructs an adjacency matrix, and iterates over subsets in a specific order to find the maximum clique efficiently.

```python
def max_clique(n_nodes, edges):
    # Input validation
    if not isinstance(n_nodes, int):
        raise ValueError("n_nodes must be an integer")
    if n_nodes < 1 or n_nodes > 20:
        raise ValueError("n_nodes must be between 1 and 20 inclusive")

    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")
    for edge in edges:
        if not isinstance(edge, tuple) or len(edge) != 2:
            raise ValueError("Each edge must be a pair (tuple of two elements)")
        u, v = edge
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError("Node indices must be integers")
        if isinstance(u, bool) or isinstance(v, bool):
            raise ValueError("Node indices must be integers, not booleans")
        if u < 0 or u >= n_nodes or v < 0 or v >= n_nodes:
            raise ValueError("Node indices out of range")

    # Build adjacency list
    adj = {i: set() for i in range(n_nodes)}
    for u, v in edges:
        if u != v:
            adj[u].add(v)
            adj[v].add(u)

    max_clique_size = 0
    max_cliques = []

    # Generate all possible subsets in order of decreasing size
    for subset_size in range(n_nodes, 0, -1):
        for subset in combinations(range(n_nodes), subset_size):
            is_clique = True
            for i in range(len(subset)):
                for j in range(i + 1, len(subset)):
                    u = subset[i]
                    v = subset[j]
                    if v not in adj[u]:
                        is_clique = False
                        break
                if not is_clique:
                    break
            if is_clique:
                max_clique_size = subset_size
                max_cliques.append(subset)
                # Since we're checking from largest to smallest, break early
                break
        if max_clique_size > 0:
            break  # No need to check smaller subsets

    # If no clique found, return the smallest node
    if not max_cliques:
        return (0,)

    # Find the lex smallest clique of maximum size
    max_cliques = [tuple(sorted(c)) for c in max_cliques]
    max_cliques = list({c for c in max_cliques if len(c) == max_clique_size})
    max_cliques.sort()
    return max_cliques[0]
