def is_graphic_degree_seq(degrees):
    def validate_input(seq):
        if not isinstance(seq, (list, tuple)):
            raise ValueError("Degrees must be a list or tuple.")
        for d in seq:
            if not isinstance(d, int) or isinstance(d, bool) or d < 0:
                raise ValueError("Invalid degree value.")
        return True

    validate_input(degrees)
    degrees = list(degrees)
    while True:
        degrees = [d for d in degrees if d != 0]
        if not degrees:
            return True
        degrees.sort(reverse=True)
        d1 = degrees[0]
        if d1 > len(degrees) - 1:
            return False
        degrees = degrees[1:]
        if d1 > len(degrees):
            return False
        for i in range(d1):
            degrees[i] -= 1
            if degrees[i] < 0:
                return False

def realize_degree_seq(degrees):
    if not is_graphic_degree_seq(degrees):
        raise ValueError("Degree sequence is not graphic.")
    degrees = list(degrees)
    n = len(degrees)
    edges = []
    nodes = sorted([(d, idx) for idx, d in enumerate(degrees)], key=lambda x: (-x[0], x[1]))
    while nodes:
        u_degree, u = nodes[0]
        if u_degree == 0:
            break
        d1 = u_degree
        if d1 > len(nodes) - 1:
            raise ValueError("Degree sequence is not graphic.")
        nodes = nodes[1:]
        for i in range(d1):
            v_degree, v = nodes[i]
            edges.append((u, v))
            nodes[i] = (v_degree - 1, v)
        nodes = [node for node in nodes if node[0] > 0]
        nodes.sort(key=lambda x: (-x[0], x[1]))
    edges.sort()
    return edges

