            if i == j:
                current_rev = prices[j-1]
                current_cuts = (j,)
            else:
                current_rev = prices[j-1] + dp[i - j] - cut_cost
                current_cuts = tuple(sorted(cuts[i - j] + (j,)))

            if current_rev > max_rev or (current_rev == max_rev and current_cuts < best_cut):
