def simulate_token_bucket(capacity, refill_rate, requests):
    # Validate capacity
    if not (isinstance(capacity, (int, float)) and not isinstance(capacity, bool)):
        raise ValueError
    if capacity <= 0:
        raise ValueError

    # Validate refill_rate
    if not (isinstance(refill_rate, (int, float)) and not isinstance(refill_rate, bool)):
        raise ValueError
    if refill_rate <= 0:
        raise ValueError

    # Validate requests
    if not isinstance(requests, (list, tuple)):
        raise ValueError

    for req in requests:
        if not isinstance(req, tuple) or len(req) != 2:
            raise ValueError
        ts, cost = req
        if not (isinstance(ts, (int, float)) and not isinstance(ts, bool)):
            raise ValueError
        if ts < 0:
            raise ValueError
        if not (isinstance(cost, (int, float)) and not isinstance(cost, bool)):
            raise ValueError
        if cost < 0:
            raise ValueError

    # Check timestamps are non-decreasing
    for i in range(1, len(requests)):
        if requests[i][0] < requests[i-1][0]:
            raise ValueError

    if not requests:
        return ([], round(float(capacity), 4))

    allowed_list = []
    tokens = float(capacity)
    last_timestamp = requests[0][0]

    for i, (t, cost) in enumerate(requests):
        if i == 0:
            delta_t = 0.0
        else:
            delta_t = t - last_timestamp

        tokens += delta_t * refill_rate
        if tokens > capacity:
            tokens = capacity

        if tokens >= cost:
            allowed = True
            tokens -= cost
        else:
            allowed = False

        allowed_list.append(allowed)
        last_timestamp = t

    remaining_tokens = round(tokens, 4)
    return (allowed_list, remaining_tokens)

