The function uses dynamic programming to compute the minimum expected search cost of an optimal BST. It validates inputs, handles edge cases, precomputes prefix sums for efficient range sum queries, and fills a DP table to find the optimal cost for all subarrays of keys. The final result is the minimum cost for the entire set of keys.

```python
def optimal_bst_cost(keys, frequencies):
    # Input validation
    if not isinstance(keys, list) or not isinstance(frequencies, list):
        raise ValueError
    if len(keys) != len(frequencies):
        raise ValueError
    for key in keys:
        if isinstance(key, bool) or not isinstance(key, (int, float)):
            raise ValueError
    for freq in frequencies:
        if isinstance(freq, bool) or not isinstance(freq, (int, float)):
            raise ValueError
        if freq < 0:
            raise ValueError
    n = len(keys)
    for i in range(1, n):
        if keys[i] <= keys[i-1]:
            raise ValueError
    if n == 0:
        return 0

    # Prefix sums for efficient range sum calculation
    prefix = [0.0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + frequencies[i]

    # Initialize DP table
    dp = [[0.0 for _ in range(n)] for __ in range(n)]

    # Fill DP table
    for l in range(1, n+1):  # l is the length of the subarray
        for i in range(n - l + 1):
            j = i + l - 1
            if i == j:
                dp[i][j] = frequencies[i]
            else:
                min_cost = float('inf')
                sum_p = prefix[j+1] - prefix[i]
                for r in range(i, j+1):
                    cost_left = dp[i][r-1] if r > i else 0.0
                    cost_right = dp[r+1][j] if r < j else 0.0
                    current_cost = cost_left + cost_right + sum_p
                    if current_cost < min_cost:
                        min_cost = current_cost
                dp[i][j] = min_cost

    # Return the result with appropriate rounding
    result = dp[0][n-1]
    if isinstance(result, int) or (isinstance(result, float) and result.is_integer()):
        return int(result)
    else:
        return round(result, 4)

