The functions `escape_c_string` and `unescape_c_string` handle C-style string escaping and unescaping. `escape_c_string` replaces specific control characters and others with their escape sequences, while `unescape_c_string` reverses this process, validating the escape sequences and raising errors for invalid cases.

```python
def escape_c_string(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    escape_dict = {
        '\n': '\\n',
        '\t': '\\t',
        '\r': '\\r',
        '\\': '\\\\',
        '"': '\\"',
        '\x00': '\\0'
    }
    result = []
    for c in text:
        if c in escape_dict:
            result.append(escape_dict[c])
        elif ord(c) < 32 or ord(c) > 126:
            hh = '{:02x}'.format(ord(c))
            result.append(f'\\x{hh}')
        else:
            result.append(c)
    return ''.join(result)

def unescape_c_string(escaped):
    if not isinstance(escaped, str):
        raise ValueError("Input must be a string.")
    i = 0
    result = []
    n = len(escaped)
    while i < n:
        if escaped[i] != '\\':
            result.append(escaped[i])
            i += 1
        else:
            if i + 1 >= n:
                raise ValueError("Trailing backslash.")
            next_char = escaped[i + 1]
            if next_char == 'x':
                if i + 3 > n:
                    raise ValueError("Incomplete hex escape.")
                hex_part = escaped[i + 2:i + 4]
                if not all(c in '0123456789abcdefABCDEF' for c in hex_part):
                    raise ValueError("Invalid hex escape.")
                value = int(hex_part, 16)
                result.append(chr(value))
                i += 4
            elif next_char in ['n', 't', 'r', '\\', '"', '0']:
                if next_char == 'n':
                    result.append('\n')
                elif next_char == 't':
                    result.append('\t')
                elif next_char == 'r':
                    result.append('\r')
                elif next_char == '\\':
                    result.append('\\')
                elif next_char == '"':
                    result.append('"')
                elif next_char == '0':
                    result.append('\x00')
                i += 2
            else:
                raise ValueError(f"Unknown escape sequence: \\{next_char}")
    return ''.join(result)
