ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'

def b58_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes or bytearray")
    if not data:
        return ""
    leading_zeros = 0
    while leading_zeros < len(data) and data[leading_zeros] == 0:
        leading_zeros += 1
    if leading_zeros == len(data):
        return '1' * leading_zeros
    num = int.from_bytes(data, byteorder='big')
    if num == 0:
        return '1' * leading_zeros
    digits = []
    while num > 0:
        remainder = num % 58
        digits.append(remainder)
        num = num // 58
    digits = digits[::-1]
    b58_str = ''.join([ALPHABET[d] for d in digits])
    return '1' * leading_zeros + b58_str

def b58_decode(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if not text:
        return b""
    leading_ones = 0
    while leading_ones < len(text) and text[leading_ones] == '1':
        leading_ones += 1
    remaining = text[leading_ones:]
    if not remaining:
        if leading_ones == 0:
            return b""
        else:
            return bytes([0] * leading_ones)
    for c in remaining:
        if c not in ALPHABET:
            raise ValueError("Invalid character in text")
    num = 0
    for c in remaining:
        num = num * 58 + ALPHABET.index(c)
    # Convert num to bytes, big-endian
    if num == 0:
        # This would only happen if remaining is all zeros, but in Base58, '0' is not allowed
        # So this case is already handled by the earlier check
        pass
    # Determine the minimal bytes needed
    if num == 0:
        byte_data = b'\x00'
    else:
        byte_data = num.to_bytes((num.bit_length() + 7) // 8, byteorder='big')
    # Prepend leading zeros
    byte_data = bytes([0] * leading_ones) + byte_data
    return byte_data

