I'll create two functions to convert between UUID bytes and URN strings. The `uuid_to_urn` function validates the input bytes, converts them to a hex string, and formats it into the URN structure. The `urn_to_uuid` function validates the URN string's format, extracts the hex part, and converts it back to bytes.

```python
def uuid_to_urn(uuid_bytes):
    if not isinstance(uuid_bytes, (bytes, bytearray)) or len(uuid_bytes) != 16:
        raise ValueError
    hex_str = uuid_bytes.hex().lower()
    return f'urn:uuid:{hex_str[:8]}-{hex_str[8:12]}-{hex_str[12:16]}-{hex_str[16:20]}-{hex_str[20:]}'

def urn_to_uuid(urn_str):
    if not isinstance(urn_str, str):
        raise ValueError
    urn_lower = urn_str.lower()
    if not urn_lower.startswith('urn:uuid:'):
        raise ValueError
    uuid_part = urn_lower[9:]
    if len(uuid_part) != 36:
        raise ValueError
    parts = uuid_part.split('-')
    if len(parts) != 5 or len(parts[0]) != 8 or len(parts[1]) != 4 or len(parts[2]) != 4 or len(parts[3]) != 4 or len(parts[4]) != 12:
        raise ValueError
    for part in parts:
        if not part.isalnum():
            raise ValueError
    hex_str = ''.join(parts)
    try:
        return bytes.fromhex(hex_str)
    except ValueError:
        raise ValueError
