To address the issue, I enhanced the `urn_to_uuid` function by using a regular expression to validate the UUID format, ensuring correct hyphen positions and only hexadecimal characters. The `uuid_to_urn` function remains unchanged as it correctly formats the UUID bytes into the required URN string.

```python
import re

def uuid_to_urn(uuid_bytes):
    if not isinstance(uuid_bytes, (bytes, bytearray)) or len(uuid_bytes) != 16:
        raise ValueError
    hex_str = uuid_bytes.hex().lower()
    return f'urn:uuid:{hex_str[:8]}-{hex_str[8:12]}-{hex_str[12:16]}-{hex_str[16:20]}-{hex_str[20:]}'

def urn_to_uuid(urn_str):
    if not isinstance(urn_str, str):
        raise ValueError
    urn_lower = urn_str.lower()
    if not urn_lower.startswith('urn:uuid:'):
        raise ValueError
    uuid_part = urn_lower[9:]
    if len(uuid_part) != 36:
        raise ValueError
    pattern = r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    if not re.fullmatch(pattern, uuid_part):
        raise ValueError
    hex_str = uuid_part.replace('-', '')
    return bytes.fromhex(hex_str)

