import re

def parse_semver(v_str):
    if not isinstance(v_str, str):
        raise ValueError("Invalid type for version string")

    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?(?:\+([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*))?$'
    match = re.fullmatch(pattern, v_str)
    if not match:
        raise ValueError("Invalid semantic version format")

    major, minor, patch = match.groups()[:3]

    # Validate numeric parts
    for part in [major, minor, patch]:
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Invalid version part: {part}")

    major = int(major)
    minor = int(minor)
    patch = int(patch)

    prerelease = ()
    prerelease_str = match.group(4)
    if prerelease_str:
        prerelease_parts = prerelease_str.split('.')
        for part in prerelease_parts:
            if not part:
                raise ValueError("Empty prerelease identifier")
            if part.isdigit():
                if len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Leading zero in prerelease identifier: {part}")
            else:
                if not re.match('^[a-zA-Z0-9-]+$', part):
                    raise ValueError(f"Invalid prerelease identifier: {part}")
        prerelease = tuple(prerelease_parts)

    build = ()
    build_str = match.group(5)
    if build_str:
        build_parts = build_str.split('.')
        for part in build_parts:
            if not part:
                raise ValueError("Empty build identifier")
            if not re.match('^[a-zA-Z0-9-]+$', part):
                raise ValueError(f"Invalid build identifier: {part}")
        build = tuple(build_parts)

    return (major, minor, patch, prerelease, build)

def compare_semver(v1_str, v2_str):
    v1 = parse_semver(v1_str)
    v2 = parse_semver(v2_str)

    # Compare major, minor, patch
    for i in range(3):
        if v1[i] < v2[i]:
            return -1
        elif v1[i] > v2[i]:
            return 1

    # Compare prerelease
    prerelease1 = v1[3]
    prerelease2 = v2[3]

    if prerelease1 == prerelease2:
        return 0

    if not prerelease1:
        return 1  # v1 has no prerelease, higher precedence
    if not prerelease2:
        return -1  # v2 has no prerelease, higher precedence

    for i in range(max(len(prerelease1), len(prerelease2))):
        part1 = prerelease1[i] if i < len(prerelease1) else None
        part2 = prerelease2[i] if i < len(prerelease2) else None

        if part1 is None:
            return -1  # v1 has fewer parts, lower precedence
        if part2 is None:
            return 1  # v2 has fewer parts, lower precedence

        # Check if parts are numeric
        if part1.isdigit() and part2.isdigit():
            num1 = int(part1)
            num2 = int(part2)
            if num1 < num2:
                return -1
            elif num1 > num2:
                return 1
        else:
            # Handle numeric vs non-numeric
            is_num1 = part1.isdigit()
            is_num2 = part2.isdigit()

            if is_num1 != is_num2:
                # Numeric identifiers have lower precedence
                if is_num1:
                    return -1
                else:
                    return 1
            else:
                # Both non-numeric or both numeric (but not both digits)
                if part1 < part2:
                    return -1
                elif part1 > part2:
                    return 1

    return 0

