def encode_tsv_row(fields):
    if not isinstance(fields, (list, tuple)):
        raise ValueError("fields must be a list or tuple")
    for field in fields:
        if not isinstance(field, str):
            raise ValueError("All elements in fields must be strings")
    escaped_fields = []
    for field in fields:
        escaped = []
        for c in field:
            if c == '\\':
                escaped.append('\\\\')
            elif c == '\t':
                escaped.append('\\t')
            elif c == '\n':
                escaped.append('\\n')
            elif c == '\r':
                escaped.append('\\r')
            else:
                escaped.append(c)
        escaped_fields.append(''.join(escaped))
    return '\t'.join(escaped_fields)

def parse_tsv_row(line):
    if not isinstance(line, str):
        raise ValueError("line must be a string")
    fields = line.split('\t')
    unescaped_fields = []
    for field in fields:
        unescaped = []
        i = 0
        while i < len(field):
            if field[i] == '\\':
                if i + 1 >= len(field):
                    raise ValueError("Trailing backslash in field")
                next_char = field[i + 1]
                if next_char == 't':
                    unescaped.append('\t')
                elif next_char == 'n':
                    unescaped.append('\n')
                elif next_char == 'r':
                    unescaped.append('\r')
                elif next_char == '\\':
                    unescaped.append('\\')
                else:
                    raise ValueError(f"Unknown escape sequence: \\{next_char}")
                i += 2
            else:
                unescaped.append(field[i])
                i += 1
        unescaped_fields.append(''.join(unescaped))
    return unescaped_fields
