def format_syslog_ts(year, month, day, hour, minute, second):
    if not all(isinstance(x, int) for x in [year, month, day, hour, minute, second]):
        raise ValueError("All parameters must be integers.")
    if isinstance(month, bool) or not (1 <= month <= 12):
        raise ValueError("Invalid month.")
    if isinstance(day, bool) or not (1 <= day <= 31):
        raise ValueError("Invalid day.")
    if isinstance(hour, bool) or not (0 <= hour <= 23):
        raise ValueError("Invalid hour.")
    if isinstance(minute, bool) or not (0 <= minute <= 59):
        raise ValueError("Invalid minute.")
    if isinstance(second, bool) or not (0 <= second <= 59):
        raise ValueError("Invalid second.")

    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    month_days = {
        1: 31, 2: 29 if is_leap(year) else 28,
        3: 31, 4:30,5:31,6:30,
        7:31,8:31,9:30,10:31,11:30,12:31
    }
    max_day = month_days[month]
    if not (1 <= day <= max_day):
        raise ValueError("Invalid day for the given month and year.")

    month_abbr = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][month-1]
    return f"{month_abbr} {day:>2d} {hour:02d}:{minute:02d}:{second:02d}"

def parse_syslog_ts(ts_str, default_year):
    if not isinstance(ts_str, str) or not isinstance(default_year, int):
