    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    month_days = {
        1: 31, 2: 29 if is_leap(default_year) else 28,
        3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
    }
    max_day = month_days[month]
    if not (1 <= day <= max_day):
        raise ValueError(f"Invalid day {day} for month {month} and year {default_year}.")

    return (default_year, month, day, hour, minute, second)

