To implement Pollard's rho algorithm for factoring a composite integer `n`, we first validate the input parameters to ensure they meet the specified constraints. We then check if `n` is a prime number, raising an error if it is. The algorithm initializes variables and iteratively updates them using a polynomial function. If a non-trivial factor is found within the allowed steps, it is returned; otherwise, `None` is returned.

```python
def pollard_rho_factor(n, max_steps=1000):
    # Input validation
    if type(n) is not int or isinstance(n, bool):
        raise ValueError
    if n <= 1:
        raise ValueError
    if type(max_steps) is not int or max_steps < 1:
        raise ValueError

    # Check if n is prime
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True

    if is_prime(n):
        raise ValueError

    # Pollard's rho algorithm
    x = 2
    y = 2
    d = 1
    for _ in range(max_steps):
        x = (x * x + 1) % n
        y = (y * y + 1) % n
        y = (y * y + 1) % n
        d = abs(x - y)
        d = gcd(d, n)
        if 1 < d < n:
            return d
        elif d == n:
            return None
    return None

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
