```python
import math

def stern_brocot_path(num, den):
    if not isinstance(num, int) or not isinstance(den, int):
        raise ValueError
    if num <= 0 or den <= 0:
        raise ValueError
    if isinstance(num, bool) or isinstance(den, bool):
        raise ValueError
    gcd = math.gcd(num, den)
    p = num // gcd
    q = den // gcd
    path = ""
    L_num, L_den = 0, 1
    R_num, R_den = 1, 0
    while True:
        M_num = L_num + R_num
        M_den = L_den + R_den
        if M_num == p and M_den == q:
            break
        elif p * M_den < q * M_num:
            path += 'L'
            R_num, R_den = M_num, M_den
        else:
            path += 'R'
            L_num, L_den = M_num, M_den
    return path

def stern_brocot_fraction(path):
    if not isinstance(path, str):
        raise ValueError
    for c in path:
        if c not in ('L', 'R'):
            raise ValueError
    L_num, L_den = 0, 1
    R_num, R_den = 1, 0
    for move in path:
        M_num = L_num + R_num
        M_den = L_den + R_den
        if move == 'L':
            R_num, R_den = M_num, M_den
        else:
            L_num, L_den = M_num, M_den
    final_num = L_num + R_num
    final_den = L_den + R_den
    gcd = math.gcd(final_num, final_den)
    return (final_num // gcd, final_den // gcd)
```

