To compute the binomial coefficient modulo a prime using Lucas' theorem, we decompose `n` and `k` into their base `p` digits. For each corresponding pair of digits, we compute the binomial coefficient modulo `p`. If any digit of `k` is greater than the corresponding digit of `n`, the result is zero. Otherwise, the product of these coefficients modulo `p` gives the final result.

```python
def comb_mod_prime(n, k, p):
    # Validate input types
    if not (isinstance(n, int) and isinstance(k, int) and isinstance(p, int)):
        raise ValueError("Inputs must be integers.")
    # Check for negative values
    if n < 0 or k < 0 or p < 2:
        raise ValueError("Negative values not allowed.")
    # Check if p is a prime
    if p < 2:
        raise ValueError("p must be a prime >= 2.")
    for i in range(2, int(p**0.5) + 1):
        if p % i == 0:
            raise ValueError("p must be a prime >= 2.")
    # Handle k > n case
    if k > n:
        return 0
    # Function to check if a number is prime
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True
    # Function to get digits in base p
    def get_digits(x, base):
        digits = []
        if x == 0:
            return [0]
        while x > 0:
            digits.append(x % base)
            x = x // base
        return digits
    # Get digits for n and k in base p
    n_digits = get_digits(n, p)
    k_digits = get_digits(k, p)
    # Pad the shorter list with zeros
    max_len = max(len(n_digits), len(k_digits))
    while len(n_digits) < max_len:
        n_digits.append(0)
    while len(k_digits) < max_len:
        k_digits.append(0)
    # Compute the product of combinations of each digit pair mod p
    result = 1
    for ni, ki in zip(n_digits, k_digits):
        if ki > ni:
            return 0
        # Compute C(ni, ki) mod p
        def comb_mod(a, b, mod):
            if b < 0 or b > a:
                return 0
            if b == 0 or b == a:
                return 1
            numerator = 1
            for i in range(a, a - b, -1):
                numerator *= i
                numerator %= mod
            denominator = 1
            for i in range(1, b + 1):
                denominator *= i
                denominator %= mod
            inv_denominator = pow(denominator, mod - 2, mod)
            return (numerator * inv_denominator) % mod
        c = comb_mod(ni, ki, p)
        if c == 0:
            return 0
        result = (result * c) % p
    return result
```

