To compute the multiplicative order of `a` modulo `n`, we first validate the inputs to ensure they are integers and `n > 1`. We then check if `a` and `n` are coprime using their greatest common divisor. If they are not, we return `None`. Using Euler's theorem, we compute Euler's totient function φ(n), which gives the maximum possible order. We find all divisors of φ(n), sorted in ascending order, and test each divisor to find the smallest one where `a^d ≡ 1 (mod n)` holds.

```python
import math

def multiplicative_order(a, n):
    # Validate input types
    if not isinstance(a, int) or not isinstance(n, int):
        raise ValueError
    if n <= 1:
        raise ValueError

    # Check if a and n are coprime
    g = math.gcd(a, n)
    if g != 1:
        return None

    # Compute Euler's totient function φ(n)
    def euler_totient(m):
        if m == 0:
            return 0
        factors = {}
        temp = m
        i = 2
        while i * i <= temp:
            while temp % i == 0:
                factors[i] = factors.get(i, 0) + 1
                temp //= i
            i += 1
        if temp > 1:
            factors[temp] = 1
        result = 1
        for p, exp in factors.items():
            result *= (p - 1) * (p ** (exp - 1))
        return result

    phi = euler_totient(n)

    # Function to get all divisors of k
    def get_divisors(k):
        divisors = set()
        for i in range(1, int(math.isqrt(k)) + 1):
            if k % i == 0:
                divisors.add(i)
                divisors.add(k // i)
        return sorted(divisors)

    divisors = get_divisors(phi)

    # Check each divisor in ascending order
    for d in divisors:
        if pow(a, d, n) == 1:
            return d
    return None  # This line is theoretically unreachable
