The function `ramanujan_sum` computes Ramanujan's sum using von Sterneck's formula. It first validates the inputs, then handles special cases for n=0 and n=1. For the general case, it calculates the greatest common divisor (gcd) of q and n, computes the Möbius function and Euler's totient function, and applies the formula.

```python
import math

def mobius(n):
    if n == 0:
        return 0
    factors = {}
    temp = n
    for i in range(2, int(math.isqrt(temp)) + 1):
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp = temp // i
    if temp > 1:
        factors[temp] = 1
    for prime in factors:
        if factors[prime] > 1:
            return 0
    return (-1) ** len(factors)

def euler_phi(n):
    if n == 0:
        return 0
    result = n
    temp = n
    for i in range(2, int(math.isqrt(temp)) + 1):
        if temp % i == 0:
            while temp % i == 0:
                temp = temp // i
            result -= result // i
    if temp > 1:
        result -= result // temp
    return result

def ramanujan_sum(q, n):
    if not isinstance(q, int) or not isinstance(n, int):
        raise ValueError
    if q < 1 or n < 0:
        raise ValueError
    if n == 0:
        return euler_phi(q)
    if q == 1:
        return 1
    if n == 1:
        return mobius(q)
    d = math.gcd(q, n)
    k = q // d
    mu = mobius(k)
    phi_q = euler_phi(q)
    phi_k = euler_phi(k)
    return mu * (phi_q // phi_k)

