To implement Andrew's monotone chain algorithm for computing the 2D convex hull, we first validate and preprocess the input points. Points are sorted lexicographically, duplicates are removed, and if fewer than three unique points remain, an error is raised. The algorithm constructs the lower and upper hulls by ensuring each new point maintains a counter-clockwise turn. The hulls are concatenated, excluding duplicate endpoints, and the result is formatted to return exact integers or rounded floats.

```python
def convex_hull_2d(points):
    # Validate input
    if not isinstance(points, (list, tuple)):
        raise ValueError("Invalid input type for points")
    if len(points) < 3:
        raise ValueError("At least 3 points are required")

    # Check each point is a 2D tuple/list with numeric coordinates
    sorted_points = []
    for p in points:
        if not isinstance(p, (list, tuple)) or len(p) != 2:
            raise ValueError("Invalid point format")
        x, y = p[0], p[1]
        if not (isinstance(x, (int, float)) and isinstance(y, (int, float))):
            raise ValueError("Invalid coordinate type")
        sorted_points.append((x, y))

    # Sort points lexicographically
    sorted_points.sort(key=lambda p: (p[0], p[1]))

    # Remove duplicates
    unique_points = []
    seen = set()
    for p in sorted_points:
        if p not in seen:
            unique_points.append(p)
            seen.add(p)

    if len(unique_points) < 3:
        raise ValueError("At least 3 unique points are required")

    # Function to compute cross product
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Build lower hull
    lower = []
    for p in unique_points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    # Build upper hull
    upper = []
    for p in reversed(unique_points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    # Concatenate and remove duplicates
    full_hull = lower[:-1] + upper[:-1]

    # Format the output
    def format_point(p):
        x, y = p
        if x == int(x):
            x = int(x)
        else:
            x = round(x, 4)
        if y == int(y):
            y = int(y)
        else:
            y = round(y, 4)
        return (x, y)

    return [format_point(p) for p in full_hull]

