The function `kruskal_mst` implements Kruskal's algorithm to find the Minimum Spanning Tree (MST) or Minimum Spanning Forest (MSF) of an undirected weighted graph. It validates input parameters, sorts edges by weight and lexicographical order, and uses a Disjoint Set Union (DSU) with path compression and union by rank to efficiently manage connected components. The algorithm processes edges in order, adding those that connect disjoint components, and returns the total weight and the sorted list of chosen edges.

```python
def kruskal_mst(n_nodes, edges):
    if not isinstance(n_nodes, int) or n_nodes < 0:
        raise ValueError("Invalid n_nodes")

    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")

    for edge in edges:
        if not isinstance(edge, tuple) or len(edge) != 3:
            raise ValueError("Each edge must be a tuple of length 3")
        u, v, weight = edge
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError("u and v must be integers")
        if u < 0 or v < 0 or u >= n_nodes or v >= n_nodes:
            raise ValueError("Vertex index out of range")
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise ValueError("Weight must be a real number")

    if n_nodes == 0:
        return (0, [])

    filtered_edges = []
    for u, v, weight in edges:
        if u == v:
            continue
        min_uv = min(u, v)
        max_uv = max(u, v)
        filtered_edges.append((weight, min_uv, max_uv))

    filtered_edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = list(range(n_nodes))
    rank = [0] * n_nodes

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u == root_v:
            return False
        if rank[root_u] > rank[root_v]:
            parent[root_v] = root_u
        else:
            parent[root_u] = root_v
            if rank[root_u] == rank[root_v]:
                rank[root_v] += 1
        return True

    chosen_edges = []
    total_weight = 0.0

    for weight, u, v in filtered_edges:
        if union(u, v):
            chosen_edges.append((u, v))
            total_weight += weight

    chosen_edges.sort(key=lambda x: (x[0], x[1]))

    if isinstance(total_weight, int):
        pass
    else:
        total_weight = round(total_weight, 4)

    return (total_weight, chosen_edges)

