        raise ValueError("Invalid r1")
    if not (isinstance(r2, (int, float)) and not isinstance(r2, bool) and r2 > 0):
        raise ValueError("Invalid r2")

    x1, y1 = c1
    x2, y2 = c2

    dx = x2 - x1
    dy = y2 - y1
    d_squared = dx**2 + dy**2
    d = math.sqrt(d_squared) if d_squared != 0 else 0.0

    # Case 1: Coincident circles
    if d < 1e-9:
        if abs(r1 - r2) < 1e-9:
            return ("coincident", ())
        else:
            return ("none", ())

    # Case 2: Separate or one inside the other
    if d > r1 + r2 or d < abs(r1 - r2) - 1e-9:
        return ("none", ())

    # Case 3: Tangent circles
    if abs(d - (r1 + r2)) < 1e-9 or abs(d - abs(r1 - r2)) < 1e-9:
        x = (r1**2 - r2**2 + d_squared) / (2 * d)
        y = math.sqrt(r1**2 - x**2)

        dir_x = dx / d if d != 0 else 0
        dir_y = dy / d if d != 0 else 0

        x_point = x1 + x * dir_x
        y_point = y1 + x * dir_y

