            y_point = y1 + (x * dir_y) - (y * dir_x)

        point = (round(x_point, 4), round(y_point, 4))
        return ("tangent", (point,))

    # Case 4: Secant circles, two intersection points
    x = (r1**2 - r2**2 + d_squared) / (2 * d)
    y = math.sqrt(r1**2 - x**2)

