def point_in_convex_poly(point, vertices):
    epsilon = 1e-9
    # Validate input types
    if not isinstance(point, (list, tuple)) or len(point) != 2:
        raise ValueError
    for coord in point:
        if not isinstance(coord, (int, float)) or isinstance(coord, bool):
            raise ValueError
    if not isinstance(vertices, (list, tuple)) or len(vertices) < 3:
        raise ValueError
    for vertex in vertices:
        if not isinstance(vertex, (list, tuple)) or len(vertex) != 2:
            raise ValueError
        for coord in vertex:
            if not isinstance(coord, (int, float)) or isinstance(coord, bool):
                raise ValueError
    # Check if point is on the boundary or outside
    n = len(vertices)
    on_boundary = False
    for i in range(n):
        x_i, y_i = vertices[i]
        x_j, y_j = vertices[(i+1) % n]
        px, py = point
        # Compute cross product
        cross = (x_j - x_i) * (py - y_i) - (y_j - y_i) * (px - x_i)
        if cross < -epsilon:
            return "outside"
        elif abs(cross) <= epsilon:
            # Check if point is on the edge segment
            min_x = min(x_i, x_j)
            max_x = max(x_i, x_j)
            min_y = min(y_i, y_j)
            max_y = max(y_i, y_j)
            if (min_x - epsilon <= px <= max_x + epsilon and
                min_y - epsilon <= py <= max_y + epsilon):
                on_boundary = True
    # After all edges
    if on_boundary:
        return "boundary"
    else:
        # Check if all cross products are positive
        for i in range(n):
            x_i, y_i = vertices[i]
            x_j, y_j = vertices[(i+1) % n]
            px, py = point
            cross = (x_j - x_i) * (py - y_i) - (y_j - y_i) * (px - x_i)
            if cross < -epsilon:
                return "outside"
        # Now check if all cross products are > epsilon
        all_inside = True
        for i in range(n):
            x_i, y_i = vertices[i]
            x_j, y_j = vertices[(i+1) % n]
            px, py = point
            cross = (x_j - x_i) * (py - y_i) - (y_j - y_i) * (px - x_i)
            if cross <= epsilon:
                all_inside = False
                break
        if all_inside:
            return "inside"
        else:
            return "outside"
