def minimum_enclosing_circle(points):
    import random
    import math

    if not isinstance(points, (list, tuple)):
        raise ValueError("Points must be a list or tuple.")
    if not all(isinstance(p, (list, tuple)) and len(p) == 2 for p in points):
        raise ValueError("Each point must be a two-element list or tuple.")
    if len(points) == 0:
        raise ValueError("Points list cannot be empty.")
    if any(not isinstance(c, (int, float)) for p in points for c in p):
        raise ValueError("Coordinates must be int or float.")

    def distance(p1, p2):
        return math.hypot(p1[0]-p2[0], p1[1]-p2[1])

    def midpoint(p1, p2):
        return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2)

    def circumcircle(p1, p2, p3):
        a = p2[0] - p1[0]
        b = p2[1] - p1[1]
        c = p3[0] - p1[0]
        d = p3[1] - p1[1]
        e = a*(p1[0] + p2[0]) + b*(p1[1] + p2[1])
        f = c*(p1[0] + p3[0]) + d*(p1[1] + p3[1])
        g = 2*(a*(p3[1] - p2[1]) - b*(p3[0] - p2[0]))
        if g == 0:
            return None
        cx = (d*e - b*f) / g
        cy = (a*f - c*e) / g
        radius = distance(p1, (cx, cy))
        return ((cx, cy), radius)

    def circle_from_points(p1, p2=None, p3=None):
        if p2 is None:
            return (p1, 0.0)
        if p3 is None:
            return (midpoint(p1, p2), distance(p1, p2) / 2)
        else:
            cc = circumcircle(p1, p2, p3)
            if cc is None:
                d1 = distance(p1, p2)
                d2 = distance(p1, p3)
                d3 = distance(p2, p3)
                max_d = max(d1, d2, d3)
                if max_d == d1:
                    return (midpoint(p1, p2), d1 / 2)
                elif max_d == d2:
                    return (midpoint(p1, p3), d2 / 2)
                else:
                    return (midpoint(p2, p3), d3 / 2)
            else:
                return cc

    def is_point_in_circle(p, circle):
        cx, cy = circle[0]
        radius = circle[1]
        dx = p[0] - cx
        dy = p[1] - cy
        return dx*dx + dy*dy <= radius * radius + 1e-14

    def welzl_helper(p, r):
        if not p:
            return circle_from_points(*r)
        if len(r) == 3:
            return circle_from_points(*r)
        idx = random.randint(0, len(p)-1)
        point = p[idx]
        p_new = p[:idx] + p[idx+1:]
        circle = welzl_helper(p_new, r)
        if is_point_in_circle(point, circle):
            return circle
        else:
            r_new = r + [point]
            return welzl_helper(p_new, r_new)

    n = len(points)
    if n == 1:
        return ( (round(points[0][0],4), round(points[0][1],4)), 0.0 )
    elif n == 2:
        mid = midpoint(points[0], points[1])
        radius = distance(points[0], points[1]) / 2
        return ( (round(mid[0],4), round(mid[1],4)), round(radius,4) )
    elif n == 3:
        d1 = distance(points[0], points[1])
        d2 = distance(points[0], points[2])
        d3 = distance(points[1], points[2])
        max_d = max(d1, d2, d3)
        if max_d == d1:
            mid = midpoint(points[0], points[1])
            radius = d1 / 2
        elif max_d == d2:
