    for p in points:
        if not all(isinstance(c, (int, float)) for c in p):
            raise ValueError("Coordinates must be int or float; bool is not allowed.")

    def format_number(x):
        rounded = round(x, 4)
        if abs(rounded - int(rounded)) < 1e-9:
            return int(rounded)
        else:
            return rounded

    def distance(p1, p2):
        return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

    def midpoint(p1, p2):
        return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2)

    def circumcircle(p1, p2, p3):
