        b = p2[1] - p1[1]
        c = p3[0] - p1[0]
        d = p3[1] - p1[1]
        e = a * (p1[0] + p2[0]) + b * (p1[1] + p2[1])
        f = c * (p1[0] + p3[0]) + d * (p1[1] + p3[1])
        g = 2 * (a * (p3[1] - p2[1]) - b * (p3[0] - p2[0]))
        if g == 0:
            return None
        cx = (d * e - b * f) / g
        cy = (a * f - c * e) / g
        radius = distance(p1, (cx, cy))
        return ((cx, cy), radius)

    def is_point_in_circle(p, circle, tolerance=1e-7):
        cx, cy = circle[0]
        radius = circle[1]
        dx = p[0] - cx
        dy = p[1] - cy
        return dx * dx + dy * dy <= (radius + tolerance) ** 2

