def tree_diameter_and_radius(n_nodes, edges):
    # Validate input types
    if not isinstance(n_nodes, int) or n_nodes < 1:
        raise ValueError("Invalid n_nodes")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")
    if len(edges) != n_nodes - 1:
        raise ValueError("Incorrect number of edges")

    # Validate each edge
    for u, v in edges:
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError("Invalid edge type")
        if u < 0 or u >= n_nodes or v < 0 or v >= n_nodes:
            raise ValueError("Invalid node index")

    # Build adjacency list
    adj = [[] for _ in range(n_nodes)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check if the graph is connected
    visited = set()
    queue = [0]
    while queue:
        node = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                queue.append(neighbor)
    if len(visited) != n_nodes:
        raise ValueError("Graph is not connected")

    if n_nodes == 1:
        return (0, 0, (0,))

    # Function to perform BFS and return parent pointers and farthest node
    def bfs(start):
        from collections import deque
        visited = {start: None}
        queue = deque([start])
        max_dist = 0
        far_node = start
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited[neighbor] = node
                    queue.append(neighbor)
                    if len(visited) - 1 > max_dist:
                        max_dist = len(visited) - 1
                        far_node = neighbor
        return visited, far_node

    # Step 1: BFS from node 0 to find u
    _, u = bfs(0)

    # Step 2: BFS from u to find v and the path
    parent_dict, v = bfs(u)

    # Reconstruct the path from u to v
    path = []
    current = v
    while current is not None:
        path.append(current)
        current = parent_dict.get(current, None)
    path = path[::-1]  # Reverse to get the path from u to v

    D = len(path) - 1  # Diameter is the number of edges
    R = (D + 1) // 2  # Radius is ceiling(D / 2)

    # Determine the center(s)
    if D % 2 == 0:
        center_index = D // 2
        centers = (path[center_index],)
    else:
        center_index1 = D // 2
        center_index2 = center_index1 + 1
        centers = (path[center_index1], path[center_index2])

    # Return as a sorted tuple
    centers = tuple(sorted(centers))
    return (D, R, centers)

