def edmonds_karp_max_flow(n_nodes, edges, source, sink):
    # Input validation
    if not isinstance(n_nodes, int) or n_nodes < 2:
        raise ValueError
    if not (isinstance(source, int) and isinstance(sink, int)):
        raise ValueError
    if source == sink or source < 0 or source >= n_nodes or sink < 0 or sink >= n_nodes:
        raise ValueError
    if not isinstance(edges, (list, tuple)):
        raise ValueError
    for edge in edges:
        if not (isinstance(edge, (list, tuple)) and len(edge) == 3):
            raise ValueError
        u, v, cap = edge
        if not (isinstance(u, int) and isinstance(v, int) and (isinstance(cap, (int, float)))):
            raise ValueError
        if u < 0 or u >= n_nodes or v < 0 or v >= n_nodes or cap < 0:
            raise ValueError

    # Build the residual graph
    class Edge:
        def __init__(self, to, rev, cap):
            self.to = to
            self.rev = rev
            self.cap = cap

    graph = [[] for _ in range(n_nodes)]
    for u, v, cap in edges:
        # Add forward edge
        forward = Edge(v, len(graph[v]), cap)
        graph[u].append(forward)
        # Add reverse edge
        reverse = Edge(u, len(graph[u]) - 1, 0)
        graph[v].append(reverse)

    max_flow = 0
    while True:
        # BFS to find the shortest augmenting path
        level = [-1] * n_nodes
        queue = []
        level[source] = 0
        queue.append(source)
        while queue:
            u = queue.pop(0)
            for edge in graph[u]:
                if edge.cap > 0 and level[edge.to] == -1:
                    level[edge.to] = level[u] + 1
                    queue.append(edge.to)
                    if edge.to == sink:
                        break
            if level[sink] != -1:
                break

        if level[sink] == -1:
            break

        # DFS to find blocking flow
        def dfs(u, flow):
            if u == sink:
                return flow
            while ptr[u] < len(graph[u]):
                edge = graph[u][ptr[u]]
                if edge.cap > 0 and level[edge.to] == level[u] + 1:
                    min_flow = min(flow, edge.cap)
                    result = dfs(edge.to, min_flow)
                    if result > 0:
                        edge.cap -= result
                        graph[edge.to][edge.rev].cap += result
                        return result
                ptr[u] += 1
            return 0

        ptr = [0] * n_nodes
        while True:
            pushed = dfs(source, float('inf'))
            if pushed == 0:
                break
            max_flow += pushed

    # Compute the min cut
    visited = [False] * n_nodes
    queue = [source]
    visited[source] = True
    while queue:
        u = queue.pop(0)
        for edge in graph[u]:
            if edge.cap > 0 and not visited[edge.to]:
                visited[edge.to] = True
                queue.append(edge.to)
    min_cut = tuple(sorted([i for i in range(n_nodes) if visited[i]]))

    # Handle max_flow as int or rounded float
    if isinstance(max_flow, int) or max_flow.is_integer():
        max_flow = int(max_flow)
    else:
        max_flow = round(max_flow, 4)

    return (max_flow, min_cut)

