    # Validate input parameters
    if not isinstance(capacity, int) or capacity < 0 or isinstance(capacity, bool):
        raise ValueError("Invalid capacity")
    if not (isinstance(items, (list, tuple))):
        raise ValueError("Items must be a list or tuple")
    seen_ids = set()
    for item in items:
        if not (isinstance(item, tuple) and len(item) == 3):
            raise ValueError("Invalid item tuple")
        weight, value, item_id = item
        if not isinstance(weight, int) or weight <= 0 or isinstance(weight, bool):
            raise ValueError("Invalid weight")
        if not isinstance(value, int) or value < 0 or isinstance(value, bool):
            raise ValueError("Invalid value")
        if not isinstance(item_id, (str, int)) or isinstance(item_id, bool):
            raise ValueError("Invalid item_id")
        if item_id == "":
            raise ValueError("Empty item_id")
        if item_id in seen_ids:
            raise ValueError("Duplicate item_id")
        seen_ids.add(item_id)

    # Handle cases where no items can be selected
    if capacity == 0 or not items:
        return (0, [])

    # Initialize DP table
    dp = [None] * (capacity + 1)
    dp[0] = {'value': 0, 'weight': 0, 'items': []}
    for w in range(1, capacity + 1):
        dp[w] = None

    # Process each item
    for item in items:
        weight, value, item_id = item
        if weight > capacity:
            continue  # Skip items that can't fit even alone
        for w in range(capacity, weight - 1, -1):
            if dp[w - weight] is not None:
                new_value = dp[w - weight]['value'] + value
                new_weight = dp[w - weight]['weight'] + weight
                new_items = dp[w - weight]['items'] + [item_id]
                # Check if current dp[w] is None or if the new subset is better
                if dp[w] is None:
                    dp[w] = {'value': new_value, 'weight': new_weight, 'items': new_items}
                else:
                    # Compare based on value, weight, and item IDs
                    if new_value > dp[w]['value']:
                        dp[w] = {'value': new_value, 'weight': new_weight, 'items': new_items}
                    elif new_value == dp[w]['value']:
                        if new_weight < dp[w]['weight']:
                            dp[w] = {'value': new_value, 'weight': new_weight, 'items': new_items}
                        elif new_weight == dp[w]['weight']:
                            # Compare lex order of sorted item IDs
                            current_sorted = sorted(dp[w]['items'])
                            new_sorted = sorted(new_items)
                            if new_sorted < current_sorted:
                                dp[w] = {'value': new_value, 'weight': new_weight, 'items': new_items}

    # Find the best subset within capacity
    max_value = -1
    best_subset = None
    for w in range(0, capacity + 1):
        if dp[w] is not None:
            if dp[w]['value'] > max_value:
                max_value = dp[w]['value']
                best_subset = dp[w]
            elif dp[w]['value'] == max_value:
                if dp[w]['weight'] < best_subset['weight']:
                    best_subset = dp[w]
                elif dp[w]['weight'] == best_subset['weight']:
                    current_sorted = sorted(best_subset['items'])
                    new_sorted = sorted(dp[w]['items'])
                    if new_sorted < current_sorted:
                        best_subset = dp[w]

    # If no items can be selected
    if best_subset is None:
        return (0, [])

    # Sort the chosen item IDs
    chosen_ids = sorted(best_subset['items'], key=lambda x: str(x))
    return (best_subset['value'], chosen_ids)

