def simulate_turing_machine(tape, transitions, start_state, accept_states, max_steps):
    # Validate input types
    if not isinstance(tape, str):
        raise ValueError("Tape must be a string.")
    if not isinstance(transitions, dict):
        raise ValueError("Transitions must be a dictionary.")
    if not isinstance(start_state, (int, str)):
        raise ValueError("Start state must be int or string.")
    if not isinstance(accept_states, (list, tuple, set)):
        raise ValueError("Accept states must be a list, tuple, or set.")
    if not isinstance(max_steps, int) or max_steps < 1:
        raise ValueError("Max steps must be a positive integer.")

    # Validate transitions
    for key, value in transitions.items():
        if len(key) != 2:
            raise ValueError("Invalid transition key length.")
        state, sym = key
        if not isinstance(state, (int, str)) or not isinstance(sym, str) or len(sym) != 1:
            raise ValueError("Invalid transition key components.")
        next_state, write_sym, direction = value
        if not isinstance(next_state, (int, str)) or not isinstance(write_sym, str) or len(write_sym) != 1:
            raise ValueError("Invalid transition value components.")
        if direction not in ('L', 'R'):
            raise ValueError("Invalid direction in transitions.")

    # Initialize tape
    tape_dict = {}
    for i, c in enumerate(tape):
        tape_dict[i] = c

    # Initialize simulation variables
    head = 0
    current_state = start_state
    steps = 0
    accept_states = set(accept_states)

    while True:
        # Check if current state is accepting
        if current_state in accept_states:
            status = "accepted"
            break

        # Check step limit
        if steps == max_steps:
            status = "step_limit"
            break

        # Read current symbol
        current_sym = tape_dict.get(head, ' ')

        # Check for transition
        transition_key = (current_state, current_sym)
        if transition_key not in transitions:
            status = "halted"
            break

        # Get transition details
        next_state, write_sym, direction = transitions[transition_key]

        # Write symbol
        if write_sym == ' ':
            if head in tape_dict:
                del tape_dict[head]
        else:
            tape_dict[head] = write_sym

        # Move head
        if direction == 'L':
            head -= 1
        else:
            head += 1

        # Update state and steps
        current_state = next_state
        steps += 1

    # Construct final tape string
    if not tape_dict:
        final_tape = ""
    else:
        min_index = min(tape_dict.keys())
        max_index = max(tape_dict.keys())
        tape_list = []
        for i in range(min_index, max_index + 1):
            tape_list.append(tape_dict.get(i, ' '))
        final_tape = ''.join(tape_list)

    return (status, steps, final_tape)

