        replace_cost = costs['replace']
        if not all(isinstance(c, int) and c >= 1 for c in (insert_cost, delete_cost, replace_cost)):
            raise ValueError
    else:
        raise ValueError

    # Initialize DP tables
    m, n = len(source), len(target)
