To implement the Round-Robin scheduling simulation with context switches, we first validate the input to ensure all constraints are met. We then use a deque to manage the ready queue. Processes are enqueued based on their arrival times, and when the ready queue is empty, we advance time to the next earliest arrival. Each process runs for a quantum or its remaining time, and context switches are accounted for. We track completion, turnaround, and waiting times for each process.

```python
from collections import deque

def simulate_round_robin(processes, quantum, context_switch):
    # Validate input parameters
    if not isinstance(processes, (list, tuple)):
        raise ValueError("Processes must be a list or tuple.")
    if not isinstance(quantum, int) or quantum < 1:
        raise ValueError("Quantum must be a positive integer.")
    if not isinstance(context_switch, int) or context_switch < 0:
        raise ValueError("Context switch must be a non-negative integer.")

    process_list = []
    pids = set()
    for proc in processes:
        if not isinstance(proc, (list, tuple)) or len(proc) != 3:
            raise ValueError("Each process must be a tuple of (pid, arrival_time, burst_time).")
        pid, arrival_time, burst_time = proc
        if not isinstance(pid, (str, int)) or isinstance(pid, bool) or pid == "":
            raise ValueError("PID must be a non-empty string or integer.")
        if pid in pids:
            raise ValueError("Duplicate PID found.")
        pids.add(pid)
        if not isinstance(arrival_time, int) or isinstance(arrival_time, bool) or arrival_time < 0:
            raise ValueError("Arrival time must be a non-negative integer.")
        if not isinstance(burst_time, int) or isinstance(burst_time, bool) or burst_time < 1:
            raise ValueError("Burst time must be a positive integer.")
        process_list.append({
            'pid': pid,
            'arrival_time': arrival_time,
            'burst_time': burst_time,
            'remaining': burst_time,
            'enqueued': False
        })

    # If no processes, return empty dict
    if not process_list:
        return {}

    # Initialize variables
    t = 0
    ready_queue = deque()
    result = {}

    # Function to find the next earliest arrival time
    def get_earliest_unarrived():
        min_time = float('inf')
        for proc in process_list:
            if not proc['enqueued'] and proc['arrival_time'] < min_time:
                min_time = proc['arrival_time']
        return min_time if min_time != float('inf') else None

    # Initial enqueue at t=0
    for proc in process_list:
        if proc['arrival_time'] == 0:
            ready_queue.append(proc)
            proc['enqueued'] = True

    while ready_queue or any(not p['enqueued'] for p in process_list):
        # If ready queue is empty, advance to next arrival time
        if not ready_queue:
            next_arrival = get_earliest_unarrived()
            if next_arrival is None:
                break  # No more processes
            t = next_arrival
            # Enqueue all processes arriving at t in input order
            for proc in process_list:
                if not proc['enqueued'] and proc['arrival_time'] == t:
                    ready_queue.append(proc)
                    proc['enqueued'] = True

        # Execute process
        current_proc = ready_queue.popleft()
        run_time = min(current_proc['remaining'], quantum)
        t += run_time
        current_proc['remaining'] -= run_time

        # Check for new arrivals during run_time
        for proc in process_list:
            if not proc['enqueued'] and proc['arrival_time'] > t - run_time and proc['arrival_time'] <= t:
                ready_queue.append(proc)
                proc['enqueued'] = True

        # Check if process finished
        if current_proc['remaining'] == 0:
            completion_time = t
            turnaround = completion_time - current_proc['arrival_time']
            waiting_time = turnaround - current_proc['burst_time']
            result[current_proc['pid']] = (completion_time, turnaround, waiting_time)
        else:
            # Put back into ready queue
            ready_queue.append(current_proc)

        # Check if context switch is needed
        if ready_queue or any(not p['enqueued'] for p in process_list):
            t += context_switch
            # Check for arrivals during context switch
            for proc in process_list:
                if not proc['enqueued'] and proc['arrival_time'] > t - context_switch and proc['arrival_time'] <= t:
                    ready_queue.append(proc)
                    proc['enqueued'] = True

    return result

