from collections import deque

def simulate_round_robin(processes, quantum, context_switch):
    # Validate input parameters
    if not isinstance(processes, (list, tuple)):
        raise ValueError("Processes must be a list or tuple")
    if not isinstance(quantum, int) or quantum < 1:
        raise ValueError("Quantum must be a positive integer")
    if not isinstance(context_switch, int) or context_switch < 0:
        raise ValueError("Context switch must be a non-negative integer")

    pids = set()
    for p in processes:
        if len(p) != 3:
            raise ValueError("Each process must be a tuple of (pid, arrival_time, burst_time)")
        pid, arrival_time, burst_time = p
        if not isinstance(pid, (int, str)) or isinstance(pid, bool):
            raise ValueError("PID must be a non-boolean string or integer")
        if pid in pids:
            raise ValueError("Duplicate PID found")
        pids.add(pid)
        if not isinstance(arrival_time, int) or isinstance(arrival_time, bool) or arrival_time < 0:
            raise ValueError("Arrival time must be a non-negative integer")
        if not isinstance(burst_time, int) or isinstance(burst_time, bool) or burst_time < 1:
            raise ValueError("Burst time must be a positive integer")

    # If no processes, return empty dict
    if not processes:
        return {}

    # Prepare process data
    process_list = []
    for pid, arrival_time, burst_time in processes:
        process_list.append({
            'pid': pid,
            'arrival_time': arrival_time,
            'burst_time': burst_time,
            'remaining': burst_time,
            'completion_time': None,
            'turnaround': None,
            'waiting_time': None
        })

    # Sort processes by arrival_time, preserving input order for same arrival times
    process_list.sort(key=lambda x: (x['arrival_time'], processes.index((x['pid'], x['arrival_time'], x['burst_time']))))

    # Create a dictionary to track arrival times and the processes arriving at those times
    arrival_dict = {}
    for p in process_list:
        key = p['arrival_time']
        if key not in arrival_dict:
            arrival_dict[key] = []
        arrival_dict[key].append(p)

    # Initialize simulation variables
    t = 0
    ready_queue = deque()

    # Function to add arrived processes to ready queue
    def add_arrived_processes(current_time):
        nonlocal arrival_dict
        to_remove = []
        for arr_time in arrival_dict:
            if arr_time <= current_time:
                for p in arrival_dict[arr_time]:
                    ready_queue.append(p)
                to_remove.append(arr_time)
        for arr_time in to_remove:
            del arrival_dict[arr_time]

    # Initial addition of processes arriving at t=0
    add_arrived_processes(t)

    # Process scheduling
    while ready_queue or arrival_dict:
        if not ready_queue:
            # Find the next earliest arrival time
            if arrival_dict:
                next_arr_time = min(arrival_dict.keys())
                t = next_arr_time
                add_arrived_processes(t)
            else:
                break

        # Execute the current process
        current_process = ready_queue.popleft()
        run_time = min(current_process['remaining'], quantum)
        t += run_time
        current_process['remaining'] -= run_time

        # Add any processes that arrived during this execution
        add_arrived_processes(t)

        # Check if process has finished
        if current_process['remaining'] == 0:
            current_process['completion_time'] = t
            current_process['turnaround'] = t - current_process['arrival_time']
            current_process['waiting_time'] = current_process['turnaround'] - current_process['burst_time']
        else:
            # Put back into ready queue
            ready_queue.append(current_process)

        # Check if context switch is needed
        if ready_queue or arrival_dict:
            t += context_switch
            # Add any processes that arrived during context switch
            add_arrived_processes(t)

