            raise ValueError

    n = len(nums)
    if n == 0:
        return (0, ())
    if n == 1:
        return (1, (nums[0],))

    # Initialize up and down arrays with tuples of (length, subseq)
    up = [ (1, (nums[0],)) ] * n
    down = [ (1, (nums[0],)) ] * n

    for i in range(1, n):
        max_up_len = 1
        max_up_subseq = (nums[i],)
        max_down_len = 1
        max_down_subseq = (nums[i],)

        for j in range(i):
            if nums[i] > nums[j]:
                current_len, current_subseq = down[j]
                new_len = current_len + 1
                new_subseq = current_subseq + (nums[i],)
                if new_len > max_up_len:
                    max_up_len = new_len
                    max_up_subseq = new_subseq
                elif new_len == max_up_len:
                    if new_subseq < max_up_subseq:
                        max_up_subseq = new_subseq
            elif nums[i] < nums[j]:
                current_len, current_subseq = up[j]
                new_len = current_len + 1
                new_subseq = current_subseq + (nums[i],)
                if new_len > max_down_len:
