                    max_down_subseq = new_subseq
                elif new_len == max_down_len:
                    if new_subseq < max_down_subseq:
                        max_down_subseq = new_subseq

        up[i] = (max_up_len, max_up_subseq)
        down[i] = (max_down_len, max_down_subseq)

    # Find the maximum length and the corresponding subsequence
