The function `subset_sum_ways` solves the problem using dynamic programming to count the number of subsets that sum to a target and determine the minimum subset size. It validates inputs, initializes DP arrays for counts and minimum sizes, and iterates through each number to update these arrays. Finally, it returns the count modulo \(10^9 + 7\) and the minimum size.

```python
MOD = 10**9 + 7

def subset_sum_ways(nums, target):
    # Input validation
    if not isinstance(nums, (list, tuple)):
        raise ValueError("nums must be a list or tuple")
    if not isinstance(target, int):
        raise ValueError("target must be an integer")
    if target < 0:
        raise ValueError("target cannot be negative")
    for x in nums:
        if not isinstance(x, int) or x <= 0:
            raise ValueError("nums must contain strictly positive integers")
        if isinstance(x, bool):
            raise ValueError("booleans are not allowed in nums")

    if target == 0:
        return (1, 0)

    # Initialize DP arrays
    max_sum = target
    count = [0] * (max_sum + 1)
    min_size = [float('inf')] * (max_sum + 1)

    count[0] = 1
    min_size[0] = 0

    for num in nums:
        for s in range(max_sum, num - 1, -1):
            if count[s - num] > 0:
                count[s] = (count[s] + count[s - num]) % MOD
                if min_size[s - num] + 1 < min_size[s]:
                    min_size[s] = min_size[s - num] + 1

    total_count = count[target] % MOD
    if total_count == 0:
        return (0, None)
    else:
        min_size_val = min_size[target] if min_size[target] != float('inf') else None
        return (total_count, min_size_val)

