def simulate_leaky_bucket(capacity, leak_rate, packets):
    # Validate capacity and leak_rate
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
        raise ValueError("Invalid capacity")
    if not isinstance(leak_rate, int) or isinstance(leak_rate, bool) or leak_rate < 1:
        raise ValueError("Invalid leak_rate")

    # Validate packets
    if not isinstance(packets, (list, tuple)):
        raise ValueError("Invalid packets type")
    arrival_times = []
    packet_ids = set()
    for packet in packets:
        if not isinstance(packet, tuple) or len(packet) != 3:
            raise ValueError("Invalid packet format")
        arrival_time, size_bytes, packet_id = packet
        if not isinstance(arrival_time, int) or isinstance(arrival_time, bool) or arrival_time < 0:
            raise ValueError("Invalid arrival_time")
        if not isinstance(size_bytes, int) or isinstance(size_bytes, bool) or size_bytes < 1:
            raise ValueError("Invalid size_bytes")
        if (not isinstance(packet_id, (str, int)) or 
            (isinstance(packet_id, bool)) or 
            (packet_id == "" and isinstance(packet_id, str))):
            raise ValueError("Invalid packet_id")
        if packet_id in packet_ids:
            raise ValueError("Duplicate packet_id")
        packet_ids.add(packet_id)
        arrival_times.append(arrival_time)

    # Check arrival times are non-decreasing
    for i in range(1, len(arrival_times)):
        if arrival_times[i] < arrival_times[i-1]:
            raise ValueError("Out-of-order arrival times")

    # Initialize simulation variables
    accepted_count = 0
    dropped_count = 0
    departures = {}
    prev_departure = 0.0  # Tracks the last departure time

    for packet in packets:
        arrival_time, size_bytes, packet_id = packet

        # Calculate buffered bytes at arrival_time
        time_since_prev = prev_departure - arrival_time
        if time_since_prev < 0:
            buffered = 0.0
        else:
            buffered = time_since_prev * leak_rate

        if buffered + size_bytes > capacity:
            dropped_count += 1
        else:
            accepted_count += 1
            start_time = max(arrival_time, prev_departure)
            dep_time = start_time + (size_bytes / leak_rate)

            # Round to 4 decimal places if necessary
            rounded = round(dep_time, 4)
            if rounded == int(rounded):
                rounded = int(rounded)
            departures[packet_id] = rounded

            prev_departure = dep_time

    return (accepted_count, dropped_count, departures)

