def max_weight_independent_set_path(weights):
    # Validate input
    if not isinstance(weights, (list, tuple)):
        raise ValueError("weights must be a list or tuple")
    if len(weights) > 100:
        raise ValueError("weights length exceeds 100")
    for w in weights:
        if isinstance(w, bool):
            raise ValueError("Booleans not accepted")
        if not isinstance(w, int):
            raise ValueError("weights must be integers")
        if w < 0:
            raise ValueError("weights must be non-negative")

    n = len(weights)
    if n == 0:
        return (0, ())

    # Initialize DP arrays
    include = [None] * n
    exclude = [None] * n

    # Each state is a tuple (weight, count, set)
    # For include[0], we must include 0
    include[0] = (weights[0], 1, (0,))
    exclude[0] = (0, 0, ())

    if n == 1:
        # Choose between include[0] and exclude[0]
        if include[0][0] > exclude[0][0]:
            return (include[0][0], include[0][2])
        else:
            return (exclude[0][0], exclude[0][2])

    # For i=1
    include[1] = (weights[1], 1, (1,))
    # exclude[1] is max between include[0] and exclude[0]
    if include[0][0] > exclude[0][0]:
        exclude[1] = include[0]
    else:
        exclude[1] = exclude[0]

    for i in range(2, n):
        # Compute include[i]
        # Can come from include[i-2] or exclude[i-2]
        candidate1 = include[i-2]
        candidate2 = exclude[i-2]
        if candidate1[0] > candidate2[0]:
            best_prev = candidate1
        elif candidate1[0] < candidate2[0]:
            best_prev = candidate2
        else:
            # Same weight, choose the one with smaller count
            if candidate1[1] < candidate2[1]:
                best_prev = candidate1
            elif candidate1[1] > candidate2[1]:
                best_prev = candidate2
            else:
                # Same count, choose the lex smaller set
                if candidate1[2] < candidate2[2]:
                    best_prev = candidate1
                else:
                    best_prev = candidate2
        new_weight = best_prev[0] + weights[i]
        new_count = best_prev[1] + 1
        new_set = best_prev[2] + (i,)
        include[i] = (new_weight, new_count, new_set)

        # Compute exclude[i]
        # Can come from include[i-1] or exclude[i-1]
        candidate1 = include[i-1]
        candidate2 = exclude[i-1]
        if candidate1[0] > candidate2[0]:
            best_prev = candidate1
        elif candidate1[0] < candidate2[0]:
            best_prev = candidate2
        else:
            # Same weight, choose the one with smaller count
            if candidate1[1] < candidate2[1]:
                best_prev = candidate1
            elif candidate1[1] > candidate2[1]:
                best_prev = candidate2
            else:
                # Same count, choose the lex smaller set
                if candidate1[2] < candidate2[2]:
                    best_prev = candidate1
                else:
                    best_prev = candidate2
        exclude[i] = best_prev

    # Now, compare include[n-1] and exclude[n-1]
    candidate1 = include[n-1]
    candidate2 = exclude[n-1]
    if candidate1[0] > candidate2[0]:
        best = candidate1
    elif candidate1[0] < candidate2[0]:
        best = candidate2
    else:
        # Same weight, choose the one with smaller count
        if candidate1[1] < candidate2[1]:
            best = candidate1
        elif candidate1[1] > candidate2[1]:
            best = candidate2
        else:
            # Same count, choose the lex smaller set
            if candidate1[2] < candidate2[2]:
                best = candidate1
            else:
                best = candidate2

    max_weight = best[0]
    chosen_indices = best[2]

    # Handle case where all weights are zero
    if max_weight == 0:
        return (0, ())

    return (max_weight, chosen_indices)
